#!/usr/bin/env python3
"""Parse `tmux capture-pane -p -e` output into a styled grid."""
import sys, re, subprocess

def parse(text):
    rows=[]
    for line in text.split('\n'):
        st={'fg':'-','bg':'-','at':set()}
        cells=[]
        i=0
        while i < len(line):
            if line[i]=='\x1b' and i+1<len(line) and line[i+1]=='[':
                j=line.index('m', i) if 'm' in line[i:] else len(line)
                params=line[i+2:j].split(';')
                k=0
                while k < len(params):
                    p=params[k]
                    p=int(p) if p.isdigit() else 0
                    if p==0: st={'fg':'-','bg':'-','at':set()}
                    elif p in (1,2,3,4,5,6,7,8,9): st['at'].add(p)
                    elif p in (21,22): st['at'].discard(1); st['at'].discard(2)
                    elif p==23: st['at'].discard(3)
                    elif p==24: st['at'].discard(4)
                    elif p==25: st['at'].discard(5); st['at'].discard(6)
                    elif p==27: st['at'].discard(7)
                    elif p==28: st['at'].discard(8)
                    elif p==29: st['at'].discard(9)
                    elif 30<=p<=37: st['fg']=str(p-30)
                    elif p==39: st['fg']='-'
                    elif 40<=p<=47: st['bg']=str(p-40)
                    elif p==49: st['bg']='-'
                    elif 90<=p<=97: st['fg']=str(p-90+8)
                    elif 100<=p<=107: st['bg']=str(p-100+8)
                    elif p in (38,48):
                        key='fg' if p==38 else 'bg'
                        if k+1<len(params) and params[k+1]=='5':
                            st[key]=params[k+2]; k+=2
                        elif k+1<len(params) and params[k+1]=='2':
                            st[key]='#%02X%02X%02X'%(int(params[k+2]),int(params[k+3]),int(params[k+4])); k+=4
                    k+=1
                i=j+1
            else:
                cells.append((line[i], st['fg'], st['bg'], ''.join(sorted(str(a) for a in st['at']))))
                i+=1
        rows.append(cells)
    return rows

def render(rows, mode):
    out=[]
    for r in rows:
        if mode=='text': out.append(''.join(c[0] for c in r))
        else:
            # runs
            s=''; cur=None; buf=''
            for c in r:
                k=(c[1],c[2],c[3])
                if k!=cur:
                    if buf: s+='[%s/%s/%s]%s'%(cur[0],cur[1],cur[2],buf)
                    cur=k; buf=''
                buf+=c[0]
            if buf: s+='[%s/%s/%s]%s'%(cur[0],cur[1],cur[2],buf)
            out.append(s)
    return '\n'.join(out)

if __name__=='__main__':
    sess=sys.argv[1] if len(sys.argv)>1 else 'tj'
    mode=sys.argv[2] if len(sys.argv)>2 else 'style'
    t=subprocess.run(['tmux','capture-pane','-p','-e','-t',sess],capture_output=True,text=True).stdout
    if t.endswith('\n'): t=t[:-1]
    print(render(parse(t),mode))
PYEOF
