//! Thin libc bindings. Rust's std already links libc on the targets we care
//! about, so the raw declarations are enough and keep the build dependency-free.

use std::io;

pub const STDIN_FD: i32 = 0;
pub const STDOUT_FD: i32 = 1;

const NCCS: usize = 32;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; NCCS],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
pub struct WinSize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: i32, buf: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, actions: i32, buf: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;

// c_iflag
const IGNBRK: u32 = 0o1;
const BRKINT: u32 = 0o2;
const PARMRK: u32 = 0o10;
const ISTRIP: u32 = 0o40;
const INLCR: u32 = 0o100;
const IGNCR: u32 = 0o200;
const ICRNL: u32 = 0o400;
const IXON: u32 = 0o2000;
// c_oflag
const OPOST: u32 = 0o1;
// c_lflag
const ECHO: u32 = 0o10;
const ECHONL: u32 = 0o100;
const ICANON: u32 = 0o2;
const ISIG: u32 = 0o1;
const IEXTEN: u32 = 0o100000;
// c_cflag
const CSIZE: u32 = 0o60;
const PARENB: u32 = 0o400;
const CS8: u32 = 0o60;

const VMIN: usize = 6;
const VTIME: usize = 5;

pub fn is_tty(fd: i32) -> bool {
    unsafe { isatty(fd) == 1 }
}

pub fn get_termios(fd: i32) -> io::Result<Termios> {
    let mut t = Termios {
        c_iflag: 0,
        c_oflag: 0,
        c_cflag: 0,
        c_lflag: 0,
        c_line: 0,
        c_cc: [0; NCCS],
        c_ispeed: 0,
        c_ospeed: 0,
    };
    if unsafe { tcgetattr(fd, &mut t) } != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(t)
}

pub fn set_termios(fd: i32, t: &Termios) -> io::Result<()> {
    if unsafe { tcsetattr(fd, TCSANOW, t) } != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

pub fn make_raw(t: &mut Termios) {
    t.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    t.c_oflag &= !OPOST;
    t.c_lflag &= !(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    t.c_cflag &= !(CSIZE | PARENB);
    t.c_cflag |= CS8;
    t.c_cc[VMIN] = 1;
    t.c_cc[VTIME] = 0;
}

pub fn window_size(fd: i32) -> io::Result<(u16, u16)> {
    let mut ws = WinSize::default();
    if unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) } != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok((ws.ws_col, ws.ws_row))
}

/// Wait until `fd` is readable. `timeout_ms` < 0 blocks forever.
pub fn wait_readable(fd: i32, timeout_ms: i32) -> bool {
    let mut p = PollFd {
        fd,
        events: 0x1, // POLLIN
        revents: 0,
    };
    unsafe { poll(&mut p, 1, timeout_ms) > 0 }
}

