//! A small immediate-mode terminal UI toolkit: geometry, styled cell buffer,
//! and an ANSI renderer that only paints the cells that actually changed.

pub mod layout;
pub mod text;
pub mod widgets;

use std::fmt::Write as _;
use std::io::Write as _;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Self {
        Rect {
            x,
            y,
            width,
            height,
        }
    }
    pub fn area(&self) -> u32 {
        self.width as u32 * self.height as u32
    }
    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn inner(&self, horizontal: u16, vertical: u16) -> Rect {
        let doubled_h = horizontal.saturating_mul(2);
        let doubled_v = vertical.saturating_mul(2);
        if self.width < doubled_h || self.height < doubled_v {
            return Rect::new(self.x, self.y, 0, 0);
        }
        Rect::new(
            self.x + horizontal,
            self.y + vertical,
            self.width - doubled_h,
            self.height - doubled_v,
        )
    }
    pub fn intersection(&self, other: Rect) -> Rect {
        let x1 = self.x.max(other.x);
        let y1 = self.y.max(other.y);
        let x2 = self.right().min(other.right());
        let y2 = self.bottom().min(other.bottom());
        Rect::new(x1, y1, x2.saturating_sub(x1), y2.saturating_sub(y1))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    Gray,
    DarkGray,
    LightRed,
    LightGreen,
    LightYellow,
    LightBlue,
    LightMagenta,
    LightCyan,
    White,
    Rgb(u8, u8, u8),
    Indexed(u8),
}

impl Color {
    /// `38;…` / `48;…` payload, matching the 256-colour form crossterm emits.
    fn ansi_payload(&self, out: &mut String) {
        match self {
            Color::Reset => unreachable!(),
            Color::Black => out.push_str("5;0"),
            Color::Red => out.push_str("5;1"),
            Color::Green => out.push_str("5;2"),
            Color::Yellow => out.push_str("5;3"),
            Color::Blue => out.push_str("5;4"),
            Color::Magenta => out.push_str("5;5"),
            Color::Cyan => out.push_str("5;6"),
            Color::Gray => out.push_str("5;7"),
            Color::DarkGray => out.push_str("5;8"),
            Color::LightRed => out.push_str("5;9"),
            Color::LightGreen => out.push_str("5;10"),
            Color::LightYellow => out.push_str("5;11"),
            Color::LightBlue => out.push_str("5;12"),
            Color::LightMagenta => out.push_str("5;13"),
            Color::LightCyan => out.push_str("5;14"),
            Color::White => out.push_str("5;15"),
            Color::Rgb(r, g, b) => {
                let _ = write!(out, "2;{};{};{}", r, g, b);
            }
            Color::Indexed(i) => {
                let _ = write!(out, "5;{}", i);
            }
        }
    }

    pub fn name(&self) -> String {
        match self {
            Color::Reset => "Reset".into(),
            Color::Black => "Black".into(),
            Color::Red => "Red".into(),
            Color::Green => "Green".into(),
            Color::Yellow => "Yellow".into(),
            Color::Blue => "Blue".into(),
            Color::Magenta => "Magenta".into(),
            Color::Cyan => "Cyan".into(),
            Color::Gray => "Gray".into(),
            Color::DarkGray => "DarkGray".into(),
            Color::LightRed => "LightRed".into(),
            Color::LightGreen => "LightGreen".into(),
            Color::LightYellow => "LightYellow".into(),
            Color::LightBlue => "LightBlue".into(),
            Color::LightMagenta => "LightMagenta".into(),
            Color::LightCyan => "LightCyan".into(),
            Color::White => "White".into(),
            Color::Rgb(r, g, b) => format!("#{:02X}{:02X}{:02X}", r, g, b),
            Color::Indexed(i) => format!("{}", i),
        }
    }

    pub fn parse(s: &str) -> Option<Color> {
        let c = match s {
            "Reset" | "reset" => Color::Reset,
            "Black" | "black" => Color::Black,
            "Red" | "red" => Color::Red,
            "Green" | "green" => Color::Green,
            "Yellow" | "yellow" => Color::Yellow,
            "Blue" | "blue" => Color::Blue,
            "Magenta" | "magenta" => Color::Magenta,
            "Cyan" | "cyan" => Color::Cyan,
            "Gray" | "gray" | "Grey" | "grey" => Color::Gray,
            "DarkGray" | "darkgray" | "DarkGrey" | "darkgrey" => Color::DarkGray,
            "LightRed" | "lightred" => Color::LightRed,
            "LightGreen" | "lightgreen" => Color::LightGreen,
            "LightYellow" | "lightyellow" => Color::LightYellow,
            "LightBlue" | "lightblue" => Color::LightBlue,
            "LightMagenta" | "lightmagenta" => Color::LightMagenta,
            "LightCyan" | "lightcyan" => Color::LightCyan,
            "White" | "white" => Color::White,
            other => {
                let hex = other.strip_prefix('#')?;
                if hex.len() != 6 {
                    return None;
                }
                let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
                Color::Rgb(r, g, b)
            }
        };
        Some(c)
    }
}

pub mod modifier {
    pub const BOLD: u16 = 0b0000_0000_0001;
    pub const DIM: u16 = 0b0000_0000_0010;
    pub const ITALIC: u16 = 0b0000_0000_0100;
    pub const UNDERLINED: u16 = 0b0000_0000_1000;
    pub const SLOW_BLINK: u16 = 0b0000_0001_0000;
    pub const RAPID_BLINK: u16 = 0b0000_0010_0000;
    pub const REVERSED: u16 = 0b0000_0100_0000;
    pub const HIDDEN: u16 = 0b0000_1000_0000;
    pub const CROSSED_OUT: u16 = 0b0001_0000_0000;

    pub const ALL: [(&str, u16); 9] = [
        ("BOLD", BOLD),
        ("DIM", DIM),
        ("ITALIC", ITALIC),
        ("UNDERLINED", UNDERLINED),
        ("SLOW_BLINK", SLOW_BLINK),
        ("RAPID_BLINK", RAPID_BLINK),
        ("REVERSED", REVERSED),
        ("HIDDEN", HIDDEN),
        ("CROSSED_OUT", CROSSED_OUT),
    ];

    pub fn to_string(bits: u16) -> String {
        let mut parts = Vec::new();
        for (name, bit) in ALL {
            if bits & bit != 0 {
                parts.push(name);
            }
        }
        parts.join(" | ")
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub underline_color: Option<Color>,
    pub add_modifier: u16,
    pub sub_modifier: u16,
}

impl Style {
    pub const fn new() -> Self {
        Style {
            fg: None,
            bg: None,
            underline_color: None,
            add_modifier: 0,
            sub_modifier: 0,
        }
    }
    pub fn fg(mut self, c: Color) -> Self {
        self.fg = Some(c);
        self
    }
    pub fn bg(mut self, c: Color) -> Self {
        self.bg = Some(c);
        self
    }
    pub fn add(mut self, m: u16) -> Self {
        self.add_modifier |= m;
        self.sub_modifier &= !m;
        self
    }
    pub fn patch(mut self, other: Style) -> Self {
        self.fg = other.fg.or(self.fg);
        self.bg = other.bg.or(self.bg);
        self.underline_color = other.underline_color.or(self.underline_color);
        self.add_modifier.remove_from(&mut self, other);
        self
    }
}

// Helper trait so `patch` reads linearly above.
trait ModifierPatch {
    fn remove_from(self, base: &mut Style, other: Style);
}
impl ModifierPatch for u16 {
    fn remove_from(self, base: &mut Style, other: Style) {
        base.add_modifier = (self & !other.sub_modifier) | other.add_modifier;
        base.sub_modifier = (base.sub_modifier & !other.add_modifier) | other.sub_modifier;
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub underline_color: Color,
    pub modifier: u16,
    /// Continuation slot of a wide grapheme; nothing is emitted for it.
    pub skip: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Cell {
            symbol: " ".to_string(),
            fg: Color::Reset,
            bg: Color::Reset,
            underline_color: Color::Reset,
            modifier: 0,
            skip: false,
        }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Self {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn set_char(&mut self, c: char) -> &mut Self {
        self.symbol.clear();
        self.symbol.push(c);
        self
    }
    pub fn set_style(&mut self, style: Style) -> &mut Self {
        if let Some(c) = style.fg {
            self.fg = c;
        }
        if let Some(c) = style.bg {
            self.bg = c;
        }
        if let Some(c) = style.underline_color {
            self.underline_color = c;
        }
        self.modifier |= style.add_modifier;
        self.modifier &= !style.sub_modifier;
        self
    }
    pub fn style(&self) -> Style {
        Style {
            fg: Some(self.fg),
            bg: Some(self.bg),
            underline_color: Some(self.underline_color),
            add_modifier: self.modifier,
            sub_modifier: 0,
        }
    }
    pub fn reset(&mut self) {
        *self = Cell::default();
    }
}

pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Self {
        let n = area.area() as usize;
        Buffer {
            area,
            content: vec![Cell::default(); n],
        }
    }
    pub fn index_of(&self, x: u16, y: u16) -> usize {
        (y - self.area.y) as usize * self.area.width as usize + (x - self.area.x) as usize
    }
    pub fn get_mut(&mut self, x: u16, y: u16) -> &mut Cell {
        let i = self.index_of(x, y);
        &mut self.content[i]
    }
    pub fn get(&self, x: u16, y: u16) -> &Cell {
        &self.content[self.index_of(x, y)]
    }
    pub fn contains(&self, x: u16, y: u16) -> bool {
        x >= self.area.x && x < self.area.right() && y >= self.area.y && y < self.area.bottom()
    }
    pub fn reset(&mut self) {
        for c in self.content.iter_mut() {
            c.reset();
        }
    }
    pub fn resize(&mut self, area: Rect) {
        self.area = area;
        self.content.clear();
        self.content.resize(area.area() as usize, Cell::default());
    }

    pub fn set_style(&mut self, area: Rect, style: Style) {
        let area = area.intersection(self.area);
        for y in area.y..area.bottom() {
            for x in area.x..area.right() {
                self.get_mut(x, y).set_style(style);
            }
        }
    }

    /// Writes `s` starting at (x, y), clipped to `max_width`. Returns the
    /// x position just past the last written cell.
    pub fn set_stringn(&mut self, x: u16, y: u16, s: &str, max_width: usize, style: Style) -> u16 {
        let mut cx = x;
        let mut remaining = max_width;
        if !self.contains(x, y) && !(y >= self.area.y && y < self.area.bottom()) {
            return x;
        }
        for g in text::graphemes(s) {
            let w = text::grapheme_width(g);
            if w == 0 {
                continue;
            }
            if w > remaining {
                break;
            }
            if !self.contains(cx, y) {
                break;
            }
            self.get_mut(cx, y).set_symbol(g).set_style(style);
            for i in 1..w {
                if self.contains(cx + i as u16, y) {
                    let c = self.get_mut(cx + i as u16, y);
                    c.reset();
                    c.skip = true;
                }
            }
            cx += w as u16;
            remaining -= w;
        }
        cx
    }

    pub fn diff<'a>(&self, other: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        let width = self.area.width as usize;
        let mut out = Vec::new();
        let mut invalidated = 0usize;
        let mut to_skip = 0usize;
        for (i, (cur, prev)) in other.content.iter().zip(self.content.iter()).enumerate() {
            if (cur != prev || invalidated > 0) && to_skip == 0 {
                let x = (i % width) as u16 + self.area.x;
                let y = (i / width) as u16 + self.area.y;
                out.push((x, y, cur));
            }
            let cur_w = text::grapheme_width(&cur.symbol);
            to_skip = cur_w.saturating_sub(1);
            let affected = text::grapheme_width(&prev.symbol).max(cur_w);
            invalidated = invalidated.max(affected).saturating_sub(1);
        }
        out
    }
}

/// Renders buffers to a terminal, keeping the previous frame for diffing.
pub struct Terminal {
    buffers: [Buffer; 2],
    current: usize,
    pub no_color: bool,
    out: std::io::BufWriter<std::io::Stdout>,
}

impl Terminal {
    pub fn new(area: Rect, no_color: bool) -> Self {
        Terminal {
            buffers: [Buffer::empty(area), Buffer::empty(area)],
            current: 0,
            no_color,
            out: std::io::BufWriter::with_capacity(64 * 1024, std::io::stdout()),
        }
    }

    pub fn size(&self) -> Rect {
        self.buffers[self.current].area
    }

    pub fn buffer_mut(&mut self) -> &mut Buffer {
        &mut self.buffers[self.current]
    }

    pub fn resize(&mut self, area: Rect) {
        self.buffers[self.current].resize(area);
        self.buffers[1 - self.current].resize(area);
        let _ = self.out.write_all(b"\x1b[2J");
    }

    pub fn flush_frame(&mut self) {
        let prev = &self.buffers[1 - self.current];
        let cur = &self.buffers[self.current];
        let updates = prev.diff(cur);
        let mut s = String::new();
        let mut last_pos: Option<(u16, u16)> = None;
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut uc = Color::Reset;
        let mut modifier = 0u16;
        for (x, y, cell) in updates {
            if !matches!(last_pos, Some((lx, ly)) if lx + 1 == x && ly == y) {
                let _ = write!(s, "\x1b[{};{}H", y + 1, x + 1);
            }
            last_pos = Some((x, y));
            if cell.modifier != modifier {
                emit_modifier_diff(&mut s, modifier, cell.modifier);
                modifier = cell.modifier;
            }
            if cell.fg != fg || cell.bg != bg {
                if cell.fg != fg {
                    emit_color(&mut s, cell.fg, true, self.no_color);
                    fg = cell.fg;
                }
                if cell.bg != bg {
                    emit_color(&mut s, cell.bg, false, self.no_color);
                    bg = cell.bg;
                }
            }
            if cell.underline_color != uc {
                emit_underline_color(&mut s, cell.underline_color, self.no_color);
                uc = cell.underline_color;
            }
            if cell.skip {
                continue;
            }
            s.push_str(&cell.symbol);
        }
        s.push_str("\x1b[39m\x1b[49m\x1b[59m\x1b[0m");
        let _ = self.out.write_all(s.as_bytes());
        let _ = self.out.flush();

        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;
    }

    pub fn write_raw(&mut self, s: &str) {
        let _ = self.out.write_all(s.as_bytes());
        let _ = self.out.flush();
    }
}

fn emit_color(s: &mut String, c: Color, foreground: bool, no_color: bool) {
    let c = if no_color { Color::Reset } else { c };
    match (c, foreground) {
        (Color::Reset, true) => s.push_str("\x1b[39m"),
        (Color::Reset, false) => s.push_str("\x1b[49m"),
        (c, true) => {
            s.push_str("\x1b[38;");
            c.ansi_payload(s);
            s.push('m');
        }
        (c, false) => {
            s.push_str("\x1b[48;");
            c.ansi_payload(s);
            s.push('m');
        }
    }
}

fn emit_underline_color(s: &mut String, c: Color, no_color: bool) {
    let c = if no_color { Color::Reset } else { c };
    match c {
        Color::Reset => s.push_str("\x1b[59m"),
        c => {
            s.push_str("\x1b[58;");
            c.ansi_payload(s);
            s.push('m');
        }
    }
}

fn emit_modifier_diff(s: &mut String, from: u16, to: u16) {
    use modifier::*;
    let removed = from & !to;
    if removed & REVERSED != 0 {
        s.push_str("\x1b[27m");
    }
    if removed & BOLD != 0 {
        s.push_str("\x1b[22m");
        if to & DIM != 0 {
            s.push_str("\x1b[2m");
        }
    }
    if removed & ITALIC != 0 {
        s.push_str("\x1b[23m");
    }
    if removed & UNDERLINED != 0 {
        s.push_str("\x1b[24m");
    }
    if removed & DIM != 0 {
        s.push_str("\x1b[22m");
    }
    if removed & CROSSED_OUT != 0 {
        s.push_str("\x1b[29m");
    }
    if removed & (SLOW_BLINK | RAPID_BLINK) != 0 {
        s.push_str("\x1b[25m");
    }
    if removed & HIDDEN != 0 {
        s.push_str("\x1b[28m");
    }
    let added = to & !from;
    if added & REVERSED != 0 {
        s.push_str("\x1b[7m");
    }
    if added & BOLD != 0 {
        s.push_str("\x1b[1m");
    }
    if added & ITALIC != 0 {
        s.push_str("\x1b[3m");
    }
    if added & UNDERLINED != 0 {
        s.push_str("\x1b[4m");
    }
    if added & DIM != 0 {
        s.push_str("\x1b[2m");
    }
    if added & CROSSED_OUT != 0 {
        s.push_str("\x1b[9m");
    }
    if added & SLOW_BLINK != 0 {
        s.push_str("\x1b[5m");
    }
    if added & RAPID_BLINK != 0 {
        s.push_str("\x1b[6m");
    }
    if added & HIDDEN != 0 {
        s.push_str("\x1b[8m");
    }
}

