//! A small immediate-mode terminal UI toolkit: geometry, styled cell buffer,
//! and an ANSI renderer that only paints the cells that actually changed.

pub mod layout;
pub mod text;
pub mod widgets;

use std::fmt::Write as _;
use std::io::Write as _;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Self {
        Rect {
            x,
            y,
            width,
            height,
        }
    }
    pub fn area(&self) -> u32 {
        self.width as u32 * self.height as u32
    }
    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn inner(&self, horizontal: u16, vertical: u16) -> Rect {
        let doubled_h = horizontal.saturating_mul(2);
        let doubled_v = vertical.saturating_mul(2);
        if self.width < doubled_h || self.height < doubled_v {
            return Rect::new(self.x, self.y, 0, 0);
        }
        Rect::new(
            self.x + horizontal,
            self.y + vertical,
            self.width - doubled_h,
            self.height - doubled_v,
        )
    }
    pub fn intersection(&self, other: Rect) -> Rect {
        let x1 = self.x.max(other.x);
        let y1 = self.y.max(other.y);
        let x2 = self.right().min(other.right());
        let y2 = self.bottom().min(other.bottom());
        Rect::new(x1, y1, x2.saturating_sub(x1), y2.saturating_sub(y1))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    Gray,
    DarkGray,
    LightRed,
    LightGreen,
    LightYellow,
    LightBlue,
    LightMagenta,
    LightCyan,
    White,
    Rgb(u8, u8, u8),
    Indexed(u8),
}

impl Color {
    /// `38;…` / `48;…` payload, matching the 256-colour form crossterm emits.
    fn ansi_payload(&self, out: &mut String) {
        match self {
            Color::Reset => unreachable!(),
            Color::Black => out.push_str("5;0"),
            Color::Red => out.push_str("5;1"),
            Color::Green => out.push_str("5;2"),
            Color::Yellow => out.push_str("5;3"),
            Color::Blue => out.push_str("5;4"),
            Color::Magenta => out.push_str("5;5"),
            Color::Cyan => out.push_str("5;6"),
            Color::Gray => out.push_str("5;7"),
            Color::DarkGray => out.push_str("5;8"),
            Color::LightRed => out.push_str("5;9"),
            Color::LightGreen => out.push_str("5;10"),
            Color::LightYellow => out.push_str("5;11"),
            Color::LightBlue => out.push_str("5;12"),
            Color::LightMagenta => out.push_str("5;13"),
            Color::LightCyan => out.push_str("5;14"),
            Color::White => out.push_str("5;15"),
            Color::Rgb(r, g, b) => {
                let _ = write!(out, "2;{};{};{}", r, g, b);
            }
            Color::Indexed(i) => {
                let _ = write!(out, "5;{}", i);
            }
        }
    }

    pub fn name(&self) -> String {
        match self {
            Color::Reset => "Reset".into(),
            Color::Black => "Black".into(),
            Color::Red => "Red".into(),
            Color::Green => "Green".into(),
            Color::Yellow => "Yellow".into(),
            Color::Blue => "Blue".into(),
            Color::Magenta => "Magenta".into(),
            Color::Cyan => "Cyan".into(),
            Color::Gray => "Gray".into(),
            Color::DarkGray => "DarkGray".into(),
            Color::LightRed => "LightRed".into(),
            Color::LightGreen => "LightGreen".into(),
            Color::LightYellow => "LightYellow".into(),
            Color::LightBlue => "LightBlue".into(),
            Color::LightMagenta => "LightMagenta".into(),
            Color::LightCyan => "LightCyan".into(),
            Color::White => "White".into(),
            Color::Rgb(r, g, b) => format!("#{:02X}{:02X}{:02X}", r, g, b),
            Color::Indexed(i) => format!("{}", i),
        }
    }

    pub fn parse(s: &str) -> Option<Color> {
        let c = match s {
            "Reset" | "reset" => Color::Reset,
            "Black" | "black" => Color::Black,
            "Red" | "red" => Color::Red,
            "Green" | "green" => Color::Green,
            "Yellow" | "yellow" => Color::Yellow,
            "Blue" | "blue" => Color::Blue,
            "Magenta" | "magenta" => Color::Magenta,
            "Cyan" | "cyan" => Color::Cyan,
            "Gray" | "gray" | "Grey" | "grey" => Color::Gray,
            "DarkGray" | "darkgray" | "DarkGrey" | "darkgrey" => Color::DarkGray,
            "LightRed" | "lightred" => Color::LightRed,
            "LightGreen" | "lightgreen" => Color::LightGreen,
            "LightYellow" | "lightyellow" => Color::LightYellow,
            "LightBlue" | "lightblue" => Color::LightBlue,
            "LightMagenta" | "lightmagenta" => Color::LightMagenta,
            "LightCyan" | "lightcyan" => Color::LightCyan,
            "White" | "white" => Color::White,
            other => {
                let hex = other.strip_prefix('#')?;
                if hex.len() != 6 {
                    return None;
                }
                let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
                Color::Rgb(r, g, b)
            }
        };
        Some(c)
    }
}

pub mod modifier {
    pub const BOLD: u16 = 0b0000_0000_0001;
    pub const DIM: u16 = 0b0000_0000_0010;
    pub const ITALIC: u16 = 0b0000_0000_0100;
    pub const UNDERLINED: u16 = 0b0000_0000_1000;
    pub const SLOW_BLINK: u16 = 0b0000_0001_0000;
    pub const RAPID_BLINK: u16 = 0b0000_0010_0000;
