//! Styled text primitives plus the grapheme/width helpers the buffer needs.

use super::Style;

/// Splits a string into grapheme-ish clusters: a base char plus any following
/// combining marks / zero-width joiners. Good enough for journal text.
pub fn graphemes(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let bytes = s.as_bytes();
    let mut start = 0usize;
    let mut iter = s.char_indices().peekable();
    while let Some((i, c)) = iter.next() {
        if i > start && !is_combining(c) {
            out.push(&s[start..i]);
            start = i;
        }
        let _ = c;
        let _ = bytes;
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

fn is_combining(c: char) -> bool {
    let cp = c as u32;
    (0x0300..=0x036F).contains(&cp)
        || (0x1AB0..=0x1AFF).contains(&cp)
        || (0x20D0..=0x20FF).contains(&cp)
        || (0xFE00..=0xFE0F).contains(&cp)
        || cp == 0x200D
}

pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if is_combining(c) {
        return 0;
    }
    if cp < 0x20 || (0x7F..0xA0).contains(&cp) {
        return 0;
    }
    if is_wide(cp) {
        2
    } else {
        1
    }
}

fn is_wide(cp: u32) -> bool {
    matches!(cp,
        0x1100..=0x115F | 0x2E80..=0x303E | 0x3041..=0x33FF | 0x3400..=0x4DBF
        | 0x4E00..=0x9FFF | 0xA000..=0xA4CF | 0xA960..=0xA97F | 0xAC00..=0xD7A3
        | 0xF900..=0xFAFF | 0xFE10..=0xFE19 | 0xFE30..=0xFE6F | 0xFF00..=0xFF60
        | 0xFFE0..=0xFFE6 | 0x1F300..=0x1F64F | 0x1F900..=0x1F9FF | 0x20000..=0x3FFFD)
}

pub fn grapheme_width(g: &str) -> usize {
    g.chars().map(char_width).max().unwrap_or(0)
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

#[derive(Clone, Debug, Default)]
pub struct Span {
    pub content: String,
    pub style: Style,
}

impl Span {
    pub fn raw<S: Into<String>>(s: S) -> Self {
        Span {
            content: s.into(),
            style: Style::new(),
        }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Self {
        Span {
            content: s.into(),
            style,
        }
    }
    pub fn width(&self) -> usize {
        str_width(&self.content)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Clone, Debug, Default)]
pub struct Line {
    pub spans: Vec<Span>,
    pub style: Style,
    pub alignment: Option<Alignment>,
}

impl Line {
    pub fn raw<S: Into<String>>(s: S) -> Self {
        Line {
            spans: vec![Span::raw(s)],
            ..Default::default()
        }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Self {
        Line {
            spans: vec![Span::styled(s, style)],
            ..Default::default()
        }
    }
    pub fn from_spans(spans: Vec<Span>) -> Self {
        Line {
            spans,
            ..Default::default()
        }
    }
    pub fn width(&self) -> usize {
        self.spans.iter().map(|s| s.width()).sum()
    }
    pub fn alignment(mut self, a: Alignment) -> Self {
        self.alignment = Some(a);
        self
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn to_plain(&self) -> String {
        self.spans.iter().map(|s| s.content.as_str()).collect()
    }
}

#[derive(Clone, Debug, Default)]
pub struct Text {
    pub lines: Vec<Line>,
    pub style: Style,
    pub alignment: Option<Alignment>,
}

impl Text {
    pub fn raw<S: AsRef<str>>(s: S) -> Self {
        Text {
            lines: s.as_ref().split('\n').map(Line::raw).collect(),
            ..Default::default()
        }
    }
    pub fn from_lines(lines: Vec<Line>) -> Self {
        Text {
            lines,
            ..Default::default()
        }
    }
    pub fn height(&self) -> usize {
        self.lines.len()
    }
    pub fn width(&self) -> usize {
        self.lines.iter().map(|l| l.width()).max().unwrap_or(0)
    }
}

/// A single styled fragment produced by the wrapper.
pub type WrappedLine = Vec<Span>;

/// Word-wraps styled spans to `max_width`. When `trim` is set, leading
/// whitespace introduced by a break is dropped (the usual paragraph look).
pub fn wrap_line(spans: &[Span], max_width: usize, trim: bool) -> Vec<WrappedLine> {
    if max_width == 0 {
        return vec![Vec::new()];
    }
    // Flatten into (grapheme, style) so wrapping can happen mid-span.
    let mut units: Vec<(String, Style, usize)> = Vec::new();
    for sp in spans {
        for g in graphemes(&sp.content) {
            let w = grapheme_width(g);
            units.push((g.to_string(), sp.style, w));
        }
    }

    let mut result: Vec<WrappedLine> = Vec::new();
    let mut current: Vec<(String, Style)> = Vec::new();
    let mut current_width = 0usize;
    // Pending word (non-whitespace run) and the whitespace that precedes it.
    let mut pending_ws: Vec<(String, Style)> = Vec::new();
    let mut pending_ws_width = 0usize;
    let mut word: Vec<(String, Style)> = Vec::new();
    let mut word_width = 0usize;
    let mut has_seen_content = false;

    macro_rules! flush_line {
        () => {{
            let mut out: WrappedLine = Vec::new();
            for (g, st) in current.drain(..) {
                match out.last_mut() {
                    Some(last) if last.style == st => last.content.push_str(&g),
                    _ => out.push(Span::styled(g, st)),
                }
            }
            result.push(out);
            current_width = 0;
        }};
    }

    macro_rules! commit_word {
        () => {{
            if !word.is_empty() {
                let ws_w = if current.is_empty() && trim {
                    0
                } else {
                    pending_ws_width
                };
                if current_width + ws_w + word_width > max_width && !current.is_empty() {
                    flush_line!();
                    pending_ws.clear();
                    pending_ws_width = 0;
                }
                if !(current.is_empty() && trim) {
                    for u in pending_ws.drain(..) {
                        current.push(u);
                    }
                    current_width += pending_ws_width;
                } else {
                    pending_ws.clear();
                }
                pending_ws_width = 0;
                // A single word longer than the line has to be split hard.
                for (g, st) in word.drain(..) {
                    let w = grapheme_width(&g);
                    if current_width + w > max_width && !current.is_empty() {
                        flush_line!();
                    }
                    current.push((g, st));
                    current_width += w;
                }
                word_width = 0;
                has_seen_content = true;
            }
        }};
    }

    for (g, st, w) in units {
        let is_ws = g == " " || g == "\t";
        if is_ws {
            commit_word!();
            pending_ws.push((g, st));
            pending_ws_width += w;
        } else {
            word.push((g, st));
            word_width += w;
        }
    }
    commit_word!();
    if !pending_ws.is_empty() && !trim {
        for (g, st) in pending_ws.drain(..) {
            let w = grapheme_width(&g);
            if current_width + w > max_width && !current.is_empty() {
                flush_line!();
            }
            current.push((g, st));
            current_width += w;
        }
    }
    let _ = has_seen_content;
    flush_line!();
    result
}

