            lines: s.as_ref().split('\n').map(Line::raw).collect(),
            ..Default::default()
        }
    }
    pub fn from_lines(lines: Vec<Line>) -> Self {
        Text {
            lines,
            ..Default::default()
        }
    }
    pub fn height(&self) -> usize {
        self.lines.len()
    }
    pub fn width(&self) -> usize {
        self.lines.iter().map(|l| l.width()).max().unwrap_or(0)
    }
}

/// A single styled fragment produced by the wrapper.
pub type WrappedLine = Vec<Span>;

/// Word-wraps styled spans to `max_width`. When `trim` is set, leading
/// whitespace introduced by a break is dropped (the usual paragraph look).
pub fn wrap_line(spans: &[Span], max_width: usize, trim: bool) -> Vec<WrappedLine> {
    if max_width == 0 {
        return vec![Vec::new()];
    }
    // Flatten into (grapheme, style) so wrapping can happen mid-span.
    let mut units: Vec<(String, Style, usize)> = Vec::new();
    for sp in spans {
        for g in graphemes(&sp.content) {
            let w = grapheme_width(g);
            units.push((g.to_string(), sp.style, w));
        }
    }

    let mut result: Vec<WrappedLine> = Vec::new();
    let mut current: Vec<(String, Style)> = Vec::new();
    let mut current_width = 0usize;
    // Pending word (non-whitespace run) and the whitespace that precedes it.
    let mut pending_ws: Vec<(String, Style)> = Vec::new();
    let mut pending_ws_width = 0usize;
    let mut word: Vec<(String, Style)> = Vec::new();
    let mut word_width = 0usize;
    let mut has_seen_content = false;

    macro_rules! flush_line {
        () => {{
            let mut out: WrappedLine = Vec::new();
            for (g, st) in current.drain(..) {
                match out.last_mut() {
                    Some(last) if last.style == st => last.content.push_str(&g),
                    _ => out.push(Span::styled(g, st)),
                }
            }
            result.push(out);
            current_width = 0;
        }};
    }

    macro_rules! commit_word {
        () => {{
            if !word.is_empty() {
                let ws_w = if current.is_empty() && trim {
                    0
                } else {
                    pending_ws_width
                };
                if current_width + ws_w + word_width > max_width && !current.is_empty() {
                    flush_line!();
                    pending_ws.clear();
                    pending_ws_width = 0;
                }
                if !(current.is_empty() && trim) {
                    for u in pending_ws.drain(..) {
                        current.push(u);
                    }
                    current_width += pending_ws_width;
                } else {
                    pending_ws.clear();
                }
                pending_ws_width = 0;
                // A single word longer than the line has to be split hard.
                for (g, st) in word.drain(..) {
                    let w = grapheme_width(&g);
                    if current_width + w > max_width && !current.is_empty() {
                        flush_line!();
                    }
                    current.push((g, st));
                    current_width += w;
                }
                word_width = 0;
                has_seen_content = true;
            }
        }};
    }

    for (g, st, w) in units {
        let is_ws = g == " " || g == "\t";
        if is_ws {
            commit_word!();
            pending_ws.push((g, st));
            pending_ws_width += w;
        } else {
            word.push((g, st));
            word_width += w;
        }
    }
    commit_word!();
    if !pending_ws.is_empty() && !trim {
        for (g, st) in pending_ws.drain(..) {
            let w = grapheme_width(&g);
            if current_width + w > max_width && !current.is_empty() {
                flush_line!();
            }
            current.push((g, st));
            current_width += w;
        }
    }
    let _ = has_seen_content;
    flush_line!();
    result
}

