//! Constraint based splitting of a `Rect`, in the spirit of the classic
//! terminal layout solvers: proportional targets, then rounded boundaries.

use super::Rect;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Constraint {
    Length(u16),
    Percentage(u16),
    Min(u16),
    Max(u16),
    Ratio(u32, u32),
    Fill(u16),
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    Horizontal,
    Vertical,
}

pub struct Layout {
    direction: Direction,
    constraints: Vec<Constraint>,
    horizontal_margin: u16,
    vertical_margin: u16,
}

impl Layout {
    pub fn new(direction: Direction, constraints: Vec<Constraint>) -> Self {
        Layout {
            direction,
            constraints,
            horizontal_margin: 0,
            vertical_margin: 0,
        }
    }
    pub fn vertical(constraints: Vec<Constraint>) -> Self {
        Layout::new(Direction::Vertical, constraints)
    }
    pub fn horizontal(constraints: Vec<Constraint>) -> Self {
        Layout::new(Direction::Horizontal, constraints)
    }
    pub fn margin(mut self, m: u16) -> Self {
        self.horizontal_margin = m;
        self.vertical_margin = m;
        self
    }
    pub fn horizontal_margin(mut self, m: u16) -> Self {
        self.horizontal_margin = m;
        self
    }
    pub fn vertical_margin(mut self, m: u16) -> Self {
        self.vertical_margin = m;
        self
    }

    pub fn split(&self, area: Rect) -> Vec<Rect> {
        let area = area.inner(self.horizontal_margin, self.vertical_margin);
        let total = match self.direction {
            Direction::Horizontal => area.width,
            Direction::Vertical => area.height,
        };
        let sizes = solve(&self.constraints, total);
        let mut out = Vec::with_capacity(sizes.len());
        let mut pos = match self.direction {
            Direction::Horizontal => area.x,
            Direction::Vertical => area.y,
        };
        for s in sizes {
            out.push(match self.direction {
                Direction::Horizontal => Rect::new(pos, area.y, s, area.height),
                Direction::Vertical => Rect::new(area.x, pos, area.width, s),
            });
            pos += s;
        }
        out
    }
}

fn solve(constraints: &[Constraint], total: u16) -> Vec<u16> {
    let n = constraints.len();
    if n == 0 {
        return Vec::new();
    }
    let total_f = total as f64;
    let mut target = vec![0f64; n];
    let mut fill_weight = vec![0f64; n];
    let mut is_flex = vec![false; n];

    for (i, c) in constraints.iter().enumerate() {
        match *c {
            Constraint::Length(v) | Constraint::Max(v) => target[i] = v as f64,
            Constraint::Min(v) => {
                target[i] = v as f64;
                is_flex[i] = true;
            }
            Constraint::Percentage(p) => target[i] = total_f * p as f64 / 100.0,
            Constraint::Ratio(a, b) => {
                target[i] = if b == 0 {
                    0.0
                } else {
                    total_f * a as f64 / b as f64
                }
            }
            Constraint::Fill(w) => {
                fill_weight[i] = w.max(1) as f64;
                is_flex[i] = true;
            }
        }
    }

    let sum: f64 = target.iter().sum();
    if sum < total_f {
        let mut extra = total_f - sum;
        let fill_total: f64 = fill_weight.iter().sum();
        if fill_total > 0.0 {
            for i in 0..n {
                if fill_weight[i] > 0.0 {
                    target[i] += extra * fill_weight[i] / fill_total;
                }
            }
        } else {
            let flex: Vec<usize> = (0..n).filter(|&i| is_flex[i]).collect();
            if !flex.is_empty() {
                let share = extra / flex.len() as f64;
                for i in flex {
                    target[i] += share;
                }
            } else {
                // Nothing wants the slack: the last segment absorbs it.
                target[n - 1] += extra;
                extra = 0.0;
            }
            let _ = extra;
        }
    } else if sum > total_f {
        // Shrink the non-flexible segments first, then everything else.
        let mut deficit = sum - total_f;
        let rigid: f64 = (0..n).filter(|&i| !is_flex[i]).map(|i| target[i]).sum();
        if rigid > 0.0 {
            let take = deficit.min(rigid);
            for i in 0..n {
                if !is_flex[i] {
                    target[i] -= take * target[i] / rigid;
                }
            }
            deficit -= take;
        }
        if deficit > 0.0 {
            let soft: f64 = (0..n).filter(|&i| is_flex[i]).map(|i| target[i]).sum();
            if soft > 0.0 {
                let take = deficit.min(soft);
                for i in 0..n {
                    if is_flex[i] {
                        target[i] -= take * target[i] / soft;
                    }
                }
            }
        }
    }

    // Round cumulative boundaries so segments stay adjacent and sum to `total`.
    let mut out = Vec::with_capacity(n);
    let mut prev_boundary = 0i64;
    let mut acc = 0f64;
    for (i, t) in target.iter().enumerate() {
        acc += *t;
        let b = if i == n - 1 {
            total as i64
        } else {
            acc.round() as i64
        };
        let b = b.clamp(prev_boundary, total as i64);
        out.push((b - prev_boundary) as u16);
        prev_boundary = b;
    }
    out
}

/// Centres a `percent_x` x `percent_y` box inside `area`.
pub fn centered_rect(percent_x: u16, percent_y: u16, area: Rect) -> Rect {
    let vert = Layout::vertical(vec![
        Constraint::Percentage((100 - percent_y) / 2),
        Constraint::Percentage(percent_y),
        Constraint::Percentage((100 - percent_y) / 2),
    ])
    .split(area);
    Layout::horizontal(vec![
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ])
    .split(vert[1])[1]
}

