//! The handful of widgets the journal UI needs.

use super::layout::{Constraint, Direction, Layout};
use super::text::{grapheme_width, graphemes, str_width, wrap_line, Alignment, Line, Span, Text};
use super::{Buffer, Color, Rect, Style};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum BorderType {
    Plain,
    Rounded,
}

impl BorderType {
    fn chars(&self) -> [&'static str; 6] {
        // top-left, top-right, bottom-left, bottom-right, horizontal, vertical
        match self {
            BorderType::Plain => ["┌", "┐", "└", "┘", "─", "│"],
            BorderType::Rounded => ["╭", "╮", "╰", "╯", "─", "│"],
        }
    }
}

pub struct Block {
    pub borders: bool,
    pub border_type: BorderType,
    pub border_style: Style,
    pub style: Style,
    pub titles: Vec<(Line, Alignment, bool)>, // line, alignment, on_bottom
    pub padding: (u16, u16, u16, u16),        // left, right, top, bottom
}

impl Default for Block {
    fn default() -> Self {
        Block {
            borders: false,
            border_type: BorderType::Plain,
            border_style: Style::new(),
            style: Style::new(),
            titles: Vec::new(),
            padding: (0, 0, 0, 0),
        }
    }
}

impl Block {
    pub fn bordered() -> Self {
        Block {
            borders: true,
            ..Default::default()
        }
    }
    pub fn border_type(mut self, t: BorderType) -> Self {
        self.border_type = t;
        self
    }
    pub fn border_style(mut self, s: Style) -> Self {
        self.border_style = s;
        self
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn title<T: Into<Line>>(mut self, t: T) -> Self {
        self.titles.push((t.into(), Alignment::Left, false));
        self
    }
    pub fn title_aligned<T: Into<Line>>(mut self, t: T, a: Alignment) -> Self {
        self.titles.push((t.into(), a, false));
        self
    }
    pub fn title_bottom<T: Into<Line>>(mut self, t: T, a: Alignment) -> Self {
        self.titles.push((t.into(), a, true));
        self
    }
    pub fn padding(mut self, l: u16, r: u16, t: u16, b: u16) -> Self {
        self.padding = (l, r, t, b);
        self
    }

    pub fn inner(&self, area: Rect) -> Rect {
        let mut r = area;
        if self.borders {
            r.x = r.x.saturating_add(1);
            r.y = r.y.saturating_add(1);
            r.width = r.width.saturating_sub(2);
            r.height = r.height.saturating_sub(2);
        }
        r.x = r.x.saturating_add(self.padding.0);
        r.width = r.width.saturating_sub(self.padding.0 + self.padding.1);
        r.y = r.y.saturating_add(self.padding.2);
        r.height = r.height.saturating_sub(self.padding.2 + self.padding.3);
        r
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.is_empty() {
            return;
        }
        buf.set_style(area, self.style);
        if self.borders {
            let c = self.border_type.chars();
            for x in area.x..area.right() {
                buf.get_mut(x, area.y)
                    .set_symbol(c[4])
                    .set_style(self.border_style);
                if area.height > 1 {
                    buf.get_mut(x, area.bottom() - 1)
                        .set_symbol(c[4])
                        .set_style(self.border_style);
                }
            }
            for y in area.y..area.bottom() {
                buf.get_mut(area.x, y)
                    .set_symbol(c[5])
                    .set_style(self.border_style);
                if area.width > 1 {
                    buf.get_mut(area.right() - 1, y)
                        .set_symbol(c[5])
                        .set_style(self.border_style);
                }
            }
            buf.get_mut(area.x, area.y)
                .set_symbol(c[0])
                .set_style(self.border_style);
            if area.width > 1 {
                buf.get_mut(area.right() - 1, area.y)
                    .set_symbol(c[1])
                    .set_style(self.border_style);
            }
            if area.height > 1 {
                buf.get_mut(area.x, area.bottom() - 1)
                    .set_symbol(c[2])
                    .set_style(self.border_style);
                if area.width > 1 {
                    buf.get_mut(area.right() - 1, area.bottom() - 1)
                        .set_symbol(c[3])
                        .set_style(self.border_style);
                }
            }
        }

        let offset = if self.borders { 1 } else { 0 };
        let avail = area.width.saturating_sub(offset * 2) as usize;
        for (line, align, bottom) in &self.titles {
            if avail == 0 {
                continue;
            }
            let y = if *bottom {
                area.bottom().saturating_sub(1)
            } else {
                area.y
            };
            if *bottom && area.height < 2 {
                continue;
            }
            let w = line.width().min(avail);
            let x = match align {
                Alignment::Left => area.x + offset,
                Alignment::Center => area.x + offset + ((avail - w) as u16) / 2,
                Alignment::Right => area.right() - offset - w as u16,
            };
            render_line_at(buf, line, x, y, w, self.style);
        }
    }
}

impl From<&str> for Line {
    fn from(s: &str) -> Line {
        Line::raw(s)
    }
}
impl From<String> for Line {
    fn from(s: String) -> Line {
        Line::raw(s)
    }
}

fn render_line_at(buf: &mut Buffer, line: &Line, x: u16, y: u16, max_w: usize, base: Style) {
    let mut cx = x;
    let mut remaining = max_w;
    for sp in &line.spans {
        if remaining == 0 {
            break;
        }
        let style = base.patch(line.style).patch(sp.style);
        let before = cx;
        cx = buf.set_stringn(cx, y, &sp.content, remaining, style);
        remaining -= (cx - before) as usize;
    }
}

pub struct Paragraph {
    pub text: Text,
    pub block: Option<Block>,
    pub wrap: Option<bool>, // Some(trim)
    pub alignment: Alignment,
    pub style: Style,
    pub scroll: (u16, u16),
}

impl Paragraph {
    pub fn new(text: Text) -> Self {
        Paragraph {
            text,
            block: None,
            wrap: None,
            alignment: Alignment::Left,
            style: Style::new(),
            scroll: (0, 0),
        }
    }
    pub fn block(mut self, b: Block) -> Self {
        self.block = Some(b);
        self
    }
    pub fn wrap(mut self, trim: bool) -> Self {
        self.wrap = Some(trim);
        self
    }
    pub fn alignment(mut self, a: Alignment) -> Self {
        self.alignment = a;
        self
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn scroll(mut self, s: (u16, u16)) -> Self {
        self.scroll = s;
        self
    }

    /// Number of rows the text occupies when wrapped to `width`.
    pub fn line_count(&self, width: u16) -> usize {
        match self.wrap {
            None => self.text.lines.len(),
            Some(trim) => self
                .text
                .lines
                .iter()
                .map(|l| wrap_line(&l.spans, width as usize, trim).len())
                .sum(),
        }
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        buf.set_style(area, self.style);
        let inner = match &self.block {
            Some(b) => {
                b.render(area, buf);
                b.inner(area)
            }
            None => area,
        };
        if inner.is_empty() {
            return;
        }
        let mut rendered: Vec<(Vec<Span>, Option<Alignment>, Style)> = Vec::new();
        for line in &self.text.lines {
            let align = line.alignment.or(self.text.alignment);
            match self.wrap {
                None => rendered.push((line.spans.clone(), align, line.style)),
                Some(trim) => {
                    for chunk in wrap_line(&line.spans, inner.width as usize, trim) {
                        rendered.push((chunk, align, line.style));
                    }
                }
            }
        }
        let base = self.style.patch(self.text.style);
        let mut y = inner.y;
        for (spans, align, lstyle) in rendered.iter().skip(self.scroll.0 as usize) {
            if y >= inner.bottom() {
                break;
            }
            let width: usize = spans.iter().map(|s| str_width(&s.content)).sum();
            let align = align.unwrap_or(self.alignment);
            let x = match align {
                Alignment::Left => inner.x,
                Alignment::Center => {
                    inner.x + (inner.width.saturating_sub(width as u16)) / 2
                }
                Alignment::Right => inner.x + inner.width.saturating_sub(width as u16),
            };
            let line = Line {
                spans: spans.clone(),
                style: *lstyle,
                alignment: None,
            };
            let start_x = if align == Alignment::Left && self.scroll.1 > 0 {
                // Horizontal scrolling only makes sense for unwrapped text.
                x
            } else {
                x
            };
            render_line_at(buf, &line, start_x, y, inner.width as usize, base);
            y += 1;
        }
    }
}

#[derive(Default, Clone)]
pub struct ListState {
    pub offset: usize,
    pub selected: Option<usize>,
}

pub struct ListItem {
    pub lines: Vec<Line>,
    pub style: Style,
}

impl ListItem {
    pub fn new(lines: Vec<Line>) -> Self {
        ListItem {
            lines,
            style: Style::new(),
        }
    }
    pub fn height(&self) -> usize {
        self.lines.len()
    }
}

pub struct List {
    pub items: Vec<ListItem>,
    pub block: Option<Block>,
    pub style: Style,
    pub highlight_style: Style,
    pub highlight_symbol: Option<String>,
}

impl List {
    pub fn new(items: Vec<ListItem>) -> Self {
        List {
            items,
            block: None,
            style: Style::new(),
            highlight_style: Style::new(),
            highlight_symbol: None,
        }
    }
    pub fn block(mut self, b: Block) -> Self {
        self.block = Some(b);
        self
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn highlight_style(mut self, s: Style) -> Self {
        self.highlight_style = s;
        self
    }
    pub fn highlight_symbol(mut self, s: &str) -> Self {
        self.highlight_symbol = Some(s.to_string());
        self
    }

    fn bounds(&self, height: usize, state: &mut ListState) -> (usize, usize) {
        let mut real_end = 0usize;
        let mut height_from_offset = 0usize;
        let mut start = state.offset.min(self.items.len());
        let mut end = start;
        for item in self.items.iter().skip(start) {
            if height_from_offset + item.height() > height {
                break;
            }
            height_from_offset += item.height();
            end += 1;
        }
        real_end = real_end.max(end);
        let selected = state.selected.unwrap_or(0).min(self.items.len().saturating_sub(1));
        while selected >= real_end {
            height_from_offset += self.items[real_end].height();
            real_end += 1;
            while height_from_offset > height {
                height_from_offset =
                    height_from_offset.saturating_sub(self.items[start].height());
                start += 1;
            }
        }
        while selected < start {
            start -= 1;
            height_from_offset += self.items[start].height();
            while height_from_offset > height {
                real_end -= 1;
                height_from_offset =
                    height_from_offset.saturating_sub(self.items[real_end].height());
            }
        }
        state.offset = start;
        (start, real_end)
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer, state: &mut ListState) {
        buf.set_style(area, self.style);
        let inner = match &self.block {
            Some(b) => {
                b.render(area, buf);
                b.inner(area)
            }
            None => area,
        };
        if inner.is_empty() || self.items.is_empty() {
            return;
        }
        let (start, end) = self.bounds(inner.height as usize, state);
        let symbol = self.highlight_symbol.clone().unwrap_or_default();
        let blank = " ".repeat(str_width(&symbol));
        let mut y = inner.y;
        for (i, item) in self.items.iter().enumerate().take(end).skip(start) {
            let selected = state.selected == Some(i);
            for (j, line) in item.lines.iter().enumerate() {
                if y >= inner.bottom() {
                    break;
                }
                let row = Rect::new(inner.x, y, inner.width, 1);
                buf.set_style(row, item.style);
                let prefix = if j == 0 { &symbol } else { &blank };
                let mut x = inner.x;
                if !symbol.is_empty() {
                    x = buf.set_stringn(x, y, prefix, inner.width as usize, item.style);
                }
                let avail = inner.right().saturating_sub(x) as usize;
                render_line_at(buf, line, x, y, avail, item.style);
                if selected {
                    buf.set_style(row, self.highlight_style);
                }
                y += 1;
            }
        }
    }
}

pub struct Tabs {
    pub titles: Vec<Line>,
    pub block: Option<Block>,
    pub selected: usize,
    pub style: Style,
    pub highlight_style: Style,
    pub divider: String,
}

impl Tabs {
    pub fn new(titles: Vec<Line>) -> Self {
        Tabs {
            titles,
            block: None,
            selected: 0,
            style: Style::new(),
            highlight_style: Style::new(),
            divider: "│".to_string(),
        }
    }
    pub fn block(mut self, b: Block) -> Self {
        self.block = Some(b);
        self
    }
    pub fn select(mut self, i: usize) -> Self {
        self.selected = i;
        self
    }
    pub fn highlight_style(mut self, s: Style) -> Self {
        self.highlight_style = s;
        self
    }
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        buf.set_style(area, self.style);
        let inner = match &self.block {
            Some(b) => {
                b.render(area, buf);
                b.inner(area)
            }
            None => area,
        };
        if inner.is_empty() {
            return;
        }
        let mut x = inner.x;
        let last = self.titles.len().saturating_sub(1);
        for (i, title) in self.titles.iter().enumerate() {
            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            x = buf.set_stringn(x, inner.y, " ", remaining, self.style);
            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            let style = if i == self.selected {
                self.style.patch(self.highlight_style)
            } else {
                self.style
            };
            let l = Line {
                spans: title.spans.clone(),
                style,
                alignment: None,
            };
            let before = x;
            render_line_at(buf, &l, x, inner.y, remaining, Style::new());
            x = before + (title.width().min(remaining)) as u16;
            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            x = buf.set_stringn(x, inner.y, " ", remaining, self.style);
            if i != last {
                let remaining = inner.right().saturating_sub(x) as usize;
                if remaining == 0 {
                    break;
                }
                x = buf.set_stringn(x, inner.y, &self.divider, remaining, self.style);
            }
        }
    }
}

pub struct Clear;

impl Clear {
    pub fn render(area: Rect, buf: &mut Buffer) {
        for y in area.y..area.bottom() {
            for x in area.x..area.right() {
                if buf.contains(x, y) {
                    buf.get_mut(x, y).reset();
                }
            }
        }
    }
}

/// Vertical scrollbar drawn on the right edge of `area`.
pub struct Scrollbar {
    pub style: Style,
}

impl Scrollbar {
    pub fn render(area: Rect, buf: &mut Buffer, content_len: usize, position: usize, style: Style) {
        if area.height < 2 || content_len == 0 {
            return;
        }
        let x = area.right().saturating_sub(1);
        buf.get_mut(x, area.y).set_symbol("▲").set_style(style);
        buf.get_mut(x, area.bottom() - 1)
            .set_symbol("▼")
            .set_style(style);
        let track = area.height.saturating_sub(2) as usize;
        if track == 0 {
            return;
        }
        let thumb_len = ((track * track) as f64 / content_len as f64).round().max(1.0) as usize;
        let thumb_len = thumb_len.min(track);
        let max_pos = content_len.saturating_sub(track).max(1);
        let thumb_start = if content_len <= track {
            0
        } else {
            ((position.min(max_pos) as f64 / max_pos as f64) * (track - thumb_len) as f64).round()
                as usize
        };
        for i in 0..track {
            let sym = if i >= thumb_start && i < thumb_start + thumb_len {
                "█"
            } else {
                "│"
            };
            buf.get_mut(x, area.y + 1 + i as u16)
                .set_symbol(sym)
                .set_style(style);
        }
    }
}

