            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            x = buf.set_stringn(x, inner.y, " ", remaining, self.style);
            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            let style = if i == self.selected {
                self.style.patch(self.highlight_style)
            } else {
                self.style
            };
            let l = Line {
                spans: title.spans.clone(),
                style,
                alignment: None,
            };
            let before = x;
            render_line_at(buf, &l, x, inner.y, remaining, Style::new());
            x = before + (title.width().min(remaining)) as u16;
            let remaining = inner.right().saturating_sub(x) as usize;
            if remaining == 0 {
                break;
            }
            x = buf.set_stringn(x, inner.y, " ", remaining, self.style);
            if i != last {
                let remaining = inner.right().saturating_sub(x) as usize;
                if remaining == 0 {
                    break;
                }
                x = buf.set_stringn(x, inner.y, &self.divider, remaining, self.style);
            }
        }
    }
}

pub struct Clear;

impl Clear {
    pub fn render(area: Rect, buf: &mut Buffer) {
        for y in area.y..area.bottom() {
            for x in area.x..area.right() {
                if buf.contains(x, y) {
                    buf.get_mut(x, y).reset();
                }
            }
        }
    }
}

/// Vertical scrollbar drawn on the right edge of `area`.
pub struct Scrollbar {
    pub style: Style,
}

impl Scrollbar {
    pub fn render(area: Rect, buf: &mut Buffer, content_len: usize, position: usize, style: Style) {
        if area.height < 2 || content_len == 0 {
            return;
        }
        let x = area.right().saturating_sub(1);
        buf.get_mut(x, area.y).set_symbol("▲").set_style(style);
        buf.get_mut(x, area.bottom() - 1)
            .set_symbol("▼")
            .set_style(style);
        let track = area.height.saturating_sub(2) as usize;
        if track == 0 {
            return;
        }
        let thumb_len = ((track * track) as f64 / content_len as f64).round().max(1.0) as usize;
        let thumb_len = thumb_len.min(track);
        let max_pos = content_len.saturating_sub(track).max(1);
        let thumb_start = if content_len <= track {
            0
        } else {
            ((position.min(max_pos) as f64 / max_pos as f64) * (track - thumb_len) as f64).round()
                as usize
        };
        for i in 0..track {
            let sym = if i >= thumb_start && i < thumb_start + thumb_len {
                "█"
            } else {
                "│"
            };
            buf.get_mut(x, area.y + 1 + i as u16)
                .set_symbol(sym)
                .set_style(style);
        }
    }
}

