//! Just enough TOML for the config and theme files: a spanned parser plus a
//! serialiser that matches the layout the app prints.

use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Array(Vec<Spanned>),
    Table(Vec<(String, Spanned)>),
}

#[derive(Clone, Debug)]
pub struct Spanned {
    pub value: Value,
    pub line: usize,
    pub col: usize,
    pub len: usize,
}

impl Spanned {
    pub fn get(&self, key: &str) -> Option<&Spanned> {
        match &self.value {
            Value::Table(t) => t.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn as_table(&self) -> Option<&Vec<(String, Spanned)>> {
        match &self.value {
            Value::Table(t) => Some(t),
            _ => None,
        }
    }
    pub fn type_name(&self) -> &'static str {
        match &self.value {
            Value::Str(_) => "string",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Bool(_) => "boolean",
            Value::Array(_) => "array",
            Value::Table(_) => "table",
        }
    }
    /// Rendering of the value used inside serde-style error messages.
    pub fn debug_value(&self) -> String {
        match &self.value {
            Value::Str(s) => format!("\"{}\"", s),
            Value::Int(i) => format!("{}", i),
            Value::Float(f) => format!("{}", f),
            Value::Bool(b) => format!("{}", b),
            Value::Array(_) => "[]".into(),
            Value::Table(_) => "{}".into(),
        }
    }
}

#[derive(Debug)]
pub struct TomlError {
    pub message: String,
    pub line: usize,
    pub col: usize,
    pub len: usize,
}

impl TomlError {
    pub fn render(&self, source: &str) -> String {
        let line_text = source.lines().nth(self.line - 1).unwrap_or("");
        let num = self.line.to_string();
        let pad = " ".repeat(num.len() + 1);
        let mut out = String::new();
        let _ = writeln!(
            out,
            "TOML parse error at line {}, column {}",
            self.line, self.col
        );
        let _ = writeln!(out, "{}|", pad);
        let _ = writeln!(out, "{} | {}", num, line_text);
        let _ = writeln!(
            out,
            "{}| {}{}",
            pad,
            " ".repeat(self.col.saturating_sub(1)),
            "^".repeat(self.len.max(1))
        );
        let _ = write!(out, "{}", self.message);
        out
    }
}

pub type Result<T> = std::result::Result<T, TomlError>;

struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Lexer {
            src: src.as_bytes(),
            pos: 0,
            line: 1,
            col: 1,
        }
    }
    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }
    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.pos + n).copied()
    }
    fn bump(&mut self) -> Option<u8> {
        let c = self.peek()?;
        self.pos += 1;
        if c == b'\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(c)
    }
    fn err<T>(&self, msg: &str) -> Result<T> {
        Err(TomlError {
            message: msg.to_string(),
            line: self.line,
            col: self.col,
            len: 1,
        })
    }
    fn skip_spaces(&mut self) {
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
            self.bump();
        }
    }
    fn skip_ws_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') => {
                    self.bump();
                }
                Some(b'#') => {
                    while let Some(c) = self.peek() {
                        if c == b'\n' {
                            break;
                        }
                        self.bump();
                    }
                }
                _ => break,
            }
        }
    }
    fn skip_to_eol(&mut self) -> Result<()> {
        self.skip_spaces();
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.bump();
                Ok(())
            }
            Some(b'\r') => {
                self.bump();
                Ok(())
            }
            Some(b'#') => {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.bump();
                }
                Ok(())
            }
            Some(_) => self.err("expected newline, found an unexpected character"),
        }
    }
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

pub fn parse(src: &str) -> Result<Spanned> {
    let mut lx = Lexer::new(src);
    let mut root: Vec<(String, Spanned)> = Vec::new();
    let mut current_path: Vec<String> = Vec::new();

    loop {
        lx.skip_ws_and_comments();
        if lx.peek().is_none() {
            break;
        }
        if lx.peek() == Some(b'[') {
            let line = lx.line;
            let col = lx.col;
            lx.bump();
            if lx.peek() == Some(b'[') {
                return lx.err("arrays of tables are not supported");
            }
            let mut path = Vec::new();
            loop {
                lx.skip_spaces();
                let k = parse_key(&mut lx)?;
                path.push(k);
                lx.skip_spaces();
                match lx.peek() {
                    Some(b'.') => {
                        lx.bump();
                    }
                    Some(b']') => {
                        lx.bump();
                        break;
                    }
                    _ => return lx.err("expected `.` or `]`"),
                }
            }
            let end_col = lx.col;
            ensure_table(&mut root, &path, line, col, end_col - col)?;
            current_path = path;
            lx.skip_to_eol()?;
        } else {
            let key_line = lx.line;
            let key_col = lx.col;
            let mut path = current_path.clone();
            let mut sub = Vec::new();
            loop {
                lx.skip_spaces();
                sub.push(parse_key(&mut lx)?);
                lx.skip_spaces();
                if lx.peek() == Some(b'.') {
                    lx.bump();
                } else {
                    break;
                }
            }
            let key_len = lx.col - key_col;
            if lx.peek() != Some(b'=') {
                return lx.err("expected `=`");
            }
            lx.bump();
            lx.skip_spaces();
            let v = parse_value(&mut lx)?;
            path.extend(sub);
            insert(&mut root, &path, v, key_line, key_col, key_len)?;
            lx.skip_to_eol()?;
        }
    }

    Ok(Spanned {
        value: Value::Table(root),
        line: 1,
        col: 1,
        len: 1,
    })
}

fn parse_key(lx: &mut Lexer) -> Result<String> {
    match lx.peek() {
        Some(b'"') | Some(b'\'') => {
            let sp = parse_value(lx)?;
            match sp.value {
                Value::Str(s) => Ok(s),
                _ => lx.err("invalid key"),
            }
        }
        Some(c) if is_bare_key_char(c) => {
            let mut s = String::new();
            while let Some(c) = lx.peek() {
                if is_bare_key_char(c) {
                    s.push(c as char);
                    lx.bump();
                } else {
                    break;
                }
            }
            Ok(s)
        }
        _ => lx.err("invalid key"),
    }
}

fn ensure_table(
    root: &mut Vec<(String, Spanned)>,
    path: &[String],
    line: usize,
    col: usize,
    len: usize,
) -> Result<()> {
    let mut cur = root;
    for (i, part) in path.iter().enumerate() {
        let idx = cur.iter().position(|(k, _)| k == part);
        let idx = match idx {
            Some(i) => i,
            None => {
                cur.push((
                    part.clone(),
                    Spanned {
                        value: Value::Table(Vec::new()),
                        line,
                        col,
                        len,
                    },
                ));
                cur.len() - 1
            }
        };
        let entry = &mut cur[idx].1;
        match &mut entry.value {
            Value::Table(t) => cur = t,
            _ => {
                return Err(TomlError {
                    message: "duplicate key".into(),
                    line,
                    col,
                    len,
                })
            }
        }
        let _ = i;
    }
    Ok(())
}

fn insert(
    root: &mut Vec<(String, Spanned)>,
    path: &[String],
    value: Spanned,
    line: usize,
    col: usize,
    len: usize,
) -> Result<()> {
    let mut cur = root;
    for part in &path[..path.len() - 1] {
        let idx = cur.iter().position(|(k, _)| k == part);
        let idx = match idx {
            Some(i) => i,
            None => {
                cur.push((
                    part.clone(),
                    Spanned {
                        value: Value::Table(Vec::new()),
                        line,
                        col,
                        len,
                    },
                ));
                cur.len() - 1
            }
        };
        match &mut cur[idx].1.value {
            Value::Table(t) => cur = t,
            _ => {
                return Err(TomlError {
                    message: "duplicate key".into(),
                    line,
                    col,
                    len,
                })
            }
        }
    }
    let last = path.last().unwrap();
    if cur.iter().any(|(k, _)| k == last) {
        return Err(TomlError {
            message: "duplicate key".into(),
            line,
            col,
            len,
        });
    }
    cur.push((last.clone(), value));
    Ok(())
}

fn parse_value(lx: &mut Lexer) -> Result<Spanned> {
    let line = lx.line;
    let col = lx.col;
    let start = lx.pos;
    let value = match lx.peek() {
        None => return lx.err("expected a value"),
        Some(b'"') => Value::Str(parse_basic_string(lx)?),
        Some(b'\'') => Value::Str(parse_literal_string(lx)?),
        Some(b'[') => {
            lx.bump();
            let mut items = Vec::new();
            loop {
                lx.skip_ws_and_comments();
                if lx.peek() == Some(b']') {
                    lx.bump();
                    break;
                }
                items.push(parse_value(lx)?);
                lx.skip_ws_and_comments();
                match lx.peek() {
                    Some(b',') => {
                        lx.bump();
                    }
                    Some(b']') => {
                        lx.bump();
                        break;
                    }
                    _ => return lx.err("expected `,` or `]`"),
                }
            }
            Value::Array(items)
        }
        Some(b'{') => {
            lx.bump();
            let mut items: Vec<(String, Spanned)> = Vec::new();
            loop {
                lx.skip_spaces();
                if lx.peek() == Some(b'}') {
                    lx.bump();
                    break;
                }
                let k = parse_key(lx)?;
                lx.skip_spaces();
                if lx.peek() != Some(b'=') {
                    return lx.err("expected `=`");
                }
                lx.bump();
                lx.skip_spaces();
                let v = parse_value(lx)?;
                items.push((k, v));
                lx.skip_spaces();
                match lx.peek() {
                    Some(b',') => {
                        lx.bump();
                    }
                    Some(b'}') => {
                        lx.bump();
                        break;
                    }
                    _ => return lx.err("expected `,` or `}`"),
                }
            }
            Value::Table(items)
        }
        Some(b't') if starts_with(lx, b"true") => {
            for _ in 0..4 {
                lx.bump();
            }
            Value::Bool(true)
        }
        Some(b'f') if starts_with(lx, b"false") => {
            for _ in 0..5 {
                lx.bump();
            }
            Value::Bool(false)
        }
        Some(_) => {
            let mut s = String::new();
            while let Some(c) = lx.peek() {
                if c == b'\n' || c == b'\r' || c == b',' || c == b']' || c == b'}' || c == b'#' {
                    break;
                }
                s.push(c as char);
                lx.bump();
            }
            let t = s.trim_end();
            // Roll the cursor back over trailing whitespace we consumed.
            let trimmed = s.len() - t.len();
            lx.pos -= trimmed;
            lx.col -= trimmed;
            if t.is_empty() {
                return lx.err("expected a value");
            }
            if let Ok(i) = t.replace('_', "").parse::<i64>() {
                Value::Int(i)
            } else if let Ok(f) = t.parse::<f64>() {
                Value::Float(f)
            } else {
                Value::Str(t.to_string())
            }
        }
    };
    Ok(Spanned {
        value,
        line,
        col,
        len: lx.pos - start,
    })
}

fn starts_with(lx: &Lexer, w: &[u8]) -> bool {
    (0..w.len()).all(|i| lx.peek_at(i) == Some(w[i]))
}

fn parse_basic_string(lx: &mut Lexer) -> Result<String> {
    if starts_with(lx, b"\"\"\"") {
        for _ in 0..3 {
            lx.bump();
        }
        if lx.peek() == Some(b'\n') {
            lx.bump();
        }
        let mut out = String::new();
        loop {
            if starts_with(lx, b"\"\"\"") {
                for _ in 0..3 {
                    lx.bump();
                }
                break;
            }
            match lx.bump() {
                None => return lx.err("unterminated string"),
                Some(c) => push_byte(&mut out, lx, c)?,
            }
        }
        return Ok(out);
    }
    lx.bump();
    let mut out = String::new();
    loop {
        match lx.bump() {
            None | Some(b'\n') => return lx.err("unterminated string"),
            Some(b'"') => break,
            Some(b'\\') => {
                let e = lx.bump();
                match e {
                    Some(b'n') => out.push('\n'),
                    Some(b't') => out.push('\t'),
                    Some(b'r') => out.push('\r'),
                    Some(b'"') => out.push('"'),
                    Some(b'\\') => out.push('\\'),
                    Some(b'0') => out.push('\0'),
                    Some(b'u') | Some(b'U') => {
                        let n = if e == Some(b'u') { 4 } else { 8 };
                        let mut v = 0u32;
                        for _ in 0..n {
                            let c = lx.bump().unwrap_or(b'0');
                            v = v * 16 + (c as char).to_digit(16).unwrap_or(0);
                        }
                        out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
                    }
                    _ => return lx.err("invalid escape sequence"),
                }
            }
            Some(c) => push_byte(&mut out, lx, c)?,
        }
    }
    Ok(out)
}

fn push_byte(out: &mut String, lx: &mut Lexer, c: u8) -> Result<()> {
    if c < 0x80 {
        out.push(c as char);
        return Ok(());
    }
    let extra = if c >> 5 == 0b110 {
        1
    } else if c >> 4 == 0b1110 {
        2
    } else {
        3
    };
    let mut bytes = vec![c];
    for _ in 0..extra {
        if let Some(b) = lx.bump() {
            bytes.push(b);
        }
    }
    out.push_str(std::str::from_utf8(&bytes).unwrap_or("\u{fffd}"));
    Ok(())
}

fn parse_literal_string(lx: &mut Lexer) -> Result<String> {
    if starts_with(lx, b"'''") {
        for _ in 0..3 {
            lx.bump();
        }
        if lx.peek() == Some(b'\n') {
            lx.bump();
        }
        let mut out = String::new();
        loop {
            if starts_with(lx, b"'''") {
                for _ in 0..3 {
                    lx.bump();
                }
                break;
            }
            match lx.bump() {
                None => return lx.err("unterminated string"),
                Some(c) => push_byte(&mut out, lx, c)?,
            }
        }
        return Ok(out);
    }
    lx.bump();
    let mut out = String::new();
    loop {
        match lx.bump() {
            None | Some(b'\n') => return lx.err("unterminated string"),
            Some(b'\'') => break,
            Some(c) => push_byte(&mut out, lx, c)?,
        }
    }
    Ok(out)
}

// ---------------------------------------------------------------- serialising

/// Builder that emits TOML in the "scalars first, then tables" order the
/// standard serialiser uses.
#[derive(Default)]
pub struct Writer {
    pub scalars: Vec<(String, String)>,
    pub tables: Vec<(String, Writer)>,
}

impl Writer {
    pub fn new() -> Self {
        Writer::default()
    }
    pub fn str_field(&mut self, k: &str, v: &str) {
        let mut s = String::new();
        escape_toml_string(&mut s, v);
        self.scalars.push((k.to_string(), s));
    }
    pub fn raw_field(&mut self, k: &str, v: String) {
        self.scalars.push((k.to_string(), v));
    }
    pub fn bool_field(&mut self, k: &str, v: bool) {
        self.scalars
            .push((k.to_string(), if v { "true".into() } else { "false".into() }));
    }
    pub fn int_field(&mut self, k: &str, v: i64) {
        self.scalars.push((k.to_string(), v.to_string()));
    }
    pub fn table(&mut self, k: &str) -> &mut Writer {
        self.tables.push((k.to_string(), Writer::new()));
        let n = self.tables.len();
        &mut self.tables[n - 1].1
    }

    pub fn render(&self) -> String {
        let mut out = String::new();
        self.render_into(&mut out, "");
        out
    }

    fn render_into(&self, out: &mut String, prefix: &str) {
        for (k, v) in &self.scalars {
            let _ = writeln!(out, "{} = {}", k, v);
        }
        for (k, t) in &self.tables {
            let path = if prefix.is_empty() {
                k.clone()
            } else {
                format!("{}.{}", prefix, k)
            };
            if !out.is_empty() {
                out.push('\n');
            }
            let _ = writeln!(out, "[{}]", path);
            t.render_into(out, &path);
        }
    }
}

pub fn escape_toml_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04X}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

