//! Application settings: defaults, `config.toml` loading and printing.

use crate::toml::{self, Spanned, TomlError, Value, Writer};
use std::path::PathBuf;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BackendType {
    Json,
    Sqlite,
}

impl BackendType {
    pub fn as_str(&self) -> &'static str {
        match self {
            BackendType::Json => "Json",
            BackendType::Sqlite => "Sqlite",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DatumVisibility {
    Show,
    Hide,
    EmptyLine,
}

impl DatumVisibility {
    pub fn as_str(&self) -> &'static str {
        match self {
            DatumVisibility::Show => "show",
            DatumVisibility::Hide => "hide",
            DatumVisibility::EmptyLine => "empty_line",
        }
    }
}

#[derive(Clone, Debug)]
pub struct ExportSettings {
    pub default_path: Option<PathBuf>,
    pub show_confirmation: bool,
}

#[derive(Clone, Debug)]
pub struct ExternalEditor {
    pub command: Option<String>,
    pub auto_save: bool,
    pub temp_file_extension: String,
}

#[derive(Clone, Debug)]
pub struct BackendFile {
    pub file_path: PathBuf,
}

#[derive(Clone, Debug)]
pub struct Settings {
    pub backend_type: BackendType,
    pub scroll_per_page: usize,
    pub sync_os_clipboard: bool,
    pub history_limit: usize,
    pub colored_tags: bool,
    pub datum_visibility: DatumVisibility,
    pub app_state_dir: PathBuf,
    pub export: ExportSettings,
