//! XDG-flavoured directory resolution.

use std::path::PathBuf;

pub struct Dirs {
    pub home: PathBuf,
    pub config_dir: PathBuf,
    pub state_dir: PathBuf,
    pub cache_dir: PathBuf,
}

fn env_path(key: &str) -> Option<PathBuf> {
    match std::env::var_os(key) {
        Some(v) if !v.is_empty() => {
            let p = PathBuf::from(v);
            if p.is_absolute() {
                Some(p)
            } else {
                None
            }
        }
        _ => None,
    }
}

impl Dirs {
    pub fn resolve() -> Dirs {
        let home = std::env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("/"));
        let config_base = env_path("XDG_CONFIG_HOME").unwrap_or_else(|| home.join(".config"));
        let state_base =
            env_path("XDG_STATE_HOME").unwrap_or_else(|| home.join(".local").join("state"));
        let cache_base = env_path("XDG_CACHE_HOME").unwrap_or_else(|| home.join(".cache"));
        Dirs {
            config_dir: config_base.join("tui-journal"),
            state_dir: state_base.join("tui-journal"),
            cache_dir: cache_base.join("tui-journal"),
            home,
        }
    }

    pub fn default_log_file(&self) -> PathBuf {
        self.cache_dir.join("tui-journal.log")
    }
}

