//! Hand-rolled argument parsing that mirrors the CLI's help and error output.

use std::path::PathBuf;

pub struct Cli {
    pub json_file_path: Option<PathBuf>,
    pub sqlite_file_path: Option<PathBuf>,
    pub backend_type: Option<crate::config::BackendType>,
    pub config: Option<PathBuf>,
    pub verbose: u8,
    pub log: Option<PathBuf>,
    pub command: Option<Command>,
}

pub enum Command {
    PrintConfig,
    ImportJournals { path: PathBuf },
    AssignPriority { priority: u32 },
    Theme(ThemeCommand),
}

pub enum ThemeCommand {
    PrintPath,
    PrintDefault,
    WriteDefaults,
}

pub struct Exit {
    pub code: i32,
    pub stdout: String,
    pub stderr: String,
}

const ABOUT: &str = "Tui app allows writing and managing journals/notes from within the terminal With different local back-ends";
const THEME_ABOUT: &str = "Provides commands regarding changing themes and styles of the app";

fn err(bin: &str, msg: String, usage: Option<String>) -> Exit {
    let mut s = format!("error: {}\n\n", msg);
    if let Some(u) = usage {
        s.push_str(&format!("Usage: {}\n\n", u));
    }
    s.push_str("For more information, try '--help'.\n");
    Exit {
        code: 2,
        stdout: String::new(),
        stderr: s,
    }
}

pub fn root_help(bin: &str, config_default: &str, log_default: &str) -> String {
    let mut s = String::new();
    s.push_str(ABOUT);
    s.push_str("\n\n");
    s.push_str(&format!("Usage: {} [OPTIONS] [COMMAND]\n\n", bin));
    s.push_str("Commands:\n");
    s.push_str("  print-config     Print the current settings including the paths for the back-end files [aliases: pc]\n");
    s.push_str("  import-journals  Import journals from the given transfer JSON file to the current back-end file [aliases: imj]\n");
    s.push_str("  assign-priority  Assign priority for all the entries with empty priority field [aliases: ap]\n");
    s.push_str(&format!(
        "  theme            {} [aliases: style]\n",
        THEME_ABOUT
    ));
    s.push_str("  help             Print this message or the help of the given subcommand(s)\n");
    s.push('\n');
    s.push_str("Options:\n");
    s.push_str("  -j, --json-file-path <FILE PATH>    Sets the entries Json file path and starts using it\n");
    s.push_str("  -s, --sqlite-file-path <FILE PATH>  Sets the entries sqlite file path and starts using it\n");
    s.push_str("  -b, --backend-type <BACKEND_TYPE>   Sets the backend type and starts using it [possible values: json, sqlite]\n");
    s.push_str("  -c, --config <DIR PATH>             Specifies the path for the configuration directory.\n");
    s.push_str("                                      Configuration files is considered as root for themes file too.\n");
    s.push_str("                                      It still accepts the path for configuration file for backward compatibility.\n");
    s.push_str(&format!(
        "                                      (default path: {})\n",
        config_default
    ));
    s.push_str("  -v, --verbose...                    Increases logging verbosity each use for up to 3 times\n");
    s.push_str("  -l, --log <FILE PATH>               Specifies a file to use for logging\n");
    s.push_str(&format!(
        "                                      (default file: {})\n",
        log_default
    ));
    s.push_str("  -h, --help                          Print help\n");
    s.push_str("  -V, --version                       Print version\n");
    s
}

fn theme_help(bin: &str) -> String {
    let mut s = String::new();
    s.push_str(THEME_ABOUT);
    s.push_str("\n\n");
    s.push_str(&format!("Usage: {} theme <COMMAND>\n\n", bin));
    s.push_str("Commands:\n");
    s.push_str("  print-path      Prints the path to the user themes file [aliases: path]\n");
    s.push_str("  print-default   Dumps the styles with the default values to be used as a reference and base for user custom themes [aliases: default]\n");
    s.push_str("  write-defaults  Creates user custom themes file if doesn't exist then writes the default styles to it [aliases: write]\n");
    s.push_str("  help            Print this message or the help of the given subcommand(s)\n");
    s.push('\n');
    s.push_str("Options:\n");
    s.push_str("  -h, --help  Print help\n");
    s
}

fn simple_help(bin: &str, about: &str, usage: &str) -> String {
    format!(
        "{}\n\nUsage: {} {}\n\nOptions:\n  -h, --help  Print help\n",
        about, bin, usage
    )
}

const PRINT_CONFIG_ABOUT: &str =
    "Print the current settings including the paths for the back-end files";
const IMPORT_ABOUT: &str =
    "Import journals from the given transfer JSON file to the current back-end file";
const ASSIGN_ABOUT: &str = "Assign priority for all the entries with empty priority field";
const THEME_PATH_ABOUT: &str = "Prints the path to the user themes file";
const THEME_DEFAULT_ABOUT: &str =
    "Dumps the styles with the default values to be used as a reference and base for user custom themes";
const THEME_WRITE_ABOUT: &str =
    "Creates user custom themes file if doesn't exist then writes the default styles to it";

fn import_help(bin: &str) -> String {
    format!(
        "{}\n\nUsage: {} import-journals --path <FILE PATH>\n\nOptions:\n  -p, --path <FILE PATH>  Path of the JSON file to import from\n  -h, --help              Print help\n",
        IMPORT_ABOUT, bin
    )
}

fn assign_help(bin: &str) -> String {
    format!(
        "{}\n\nUsage: {} assign-priority <PRIORITY>\n\nArguments:\n  <PRIORITY>  Priority value (Positive number)\n\nOptions:\n  -h, --help  Print help\n",
        ASSIGN_ABOUT, bin
    )
}

fn out(s: String) -> Exit {
    Exit {
        code: 0,
        stdout: s,
        stderr: String::new(),
    }
}

pub struct Env<'a> {
    pub bin: &'a str,
    pub config_default: &'a str,
    pub log_default: &'a str,
    pub version: &'a str,
}

/// Parses argv. `Ok` carries the parsed CLI, `Err` an early exit (help,
/// version, or a usage error) with the exact text to print.
pub fn parse(args: &[String], env: &Env) -> Result<Cli, Exit> {
    let bin = env.bin;
    let mut cli = Cli {
        json_file_path: None,
        sqlite_file_path: None,
        backend_type: None,
        config: None,
        verbose: 0,
        log: None,
        command: None,
    };
    let mut i = 0;
    let mut positional: Vec<String> = Vec::new();
    let mut no_more_flags = false;

    while i < args.len() {
        let a = &args[i];
        if !no_more_flags && a == "--" {
            no_more_flags = true;
            i += 1;
            continue;
        }
        if !no_more_flags && a.starts_with("--") {
            let (name, inline) = match a.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (a.as_str(), None),
            };
            match name {
                "--help" => return Err(out(root_help(bin, env.config_default, env.log_default))),
                "--version" => return Err(out(format!("{}\n", env.version))),
                "--verbose" => cli.verbose = (cli.verbose + 1).min(3),
                "--json-file-path" | "--sqlite-file-path" | "--backend-type" | "--config"
                | "--log" => {
                    let value_name = match name {
                        "--backend-type" => "BACKEND_TYPE",
                        "--config" => "DIR PATH",
                        _ => "FILE PATH",
                    };
                    let v = match inline {
                        Some(v) => v,
                        None => {
                            i += 1;
                            match args.get(i) {
                                Some(v) => v.clone(),
                                None => {
                                    return Err(err(
                                        bin,
                                        format!(
                                            "a value is required for '{} <{}>' but none was supplied",
                                            name, value_name
                                        ),
                                        None,
                                    ))
                                }
                            }
                        }
                    };
                    assign_option(&mut cli, name, &v, bin)?;
                }
                _ => {
                    let tip = suggest_long(name);
                    let mut msg = format!("unexpected argument '{}' found", a);
                    let usage = match &tip {
                        Some((long, value)) => {
                            msg.push_str(&format!(
                                "\n\n  tip: a similar argument exists: '{}'",
                                long
                            ));
                            format!("{} {} <{}>", bin, long, value)
                        }
                        None => format!("{} [OPTIONS] [COMMAND]", bin),
                    };
                    return Err(err(bin, msg, Some(usage)));
                }
            }
            i += 1;
            continue;
        }
        if !no_more_flags && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0;
            let mut consumed_value = false;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Err(out(root_help(bin, env.config_default, env.log_default))),
                    'V' => return Err(out(format!("{}\n", env.version))),
                    'v' => cli.verbose = (cli.verbose + 1).min(3),
                    'j' | 's' | 'b' | 'c' | 'l' => {
                        let long = match c {
                            'j' => "--json-file-path",
                            's' => "--sqlite-file-path",
                            'b' => "--backend-type",
                            'c' => "--config",
                            _ => "--log",
                        };
                        let value_name = match c {
                            'b' => "BACKEND_TYPE",
                            'c' => "DIR PATH",
                            _ => "FILE PATH",
                        };
                        let rest: String = chars[ci + 1..].iter().collect();
                        let v = if !rest.is_empty() {
                            rest
                        } else {
                            i += 1;
                            consumed_value = true;
                            match args.get(i) {
                                Some(v) => v.clone(),
                                None => {
                                    return Err(err(
                                        bin,
                                        format!(
                                            "a value is required for '{} <{}>' but none was supplied",
                                            long, value_name
                                        ),
                                        None,
                                    ))
                                }
                            }
                        };
                        assign_option(&mut cli, long, &v, bin)?;
                        ci = chars.len();
                        let _ = consumed_value;
                        continue;
                    }
                    _ => {
                        return Err(err(
                            bin,
                            format!("unexpected argument '{}' found", a),
                            Some(format!("{} [OPTIONS] [COMMAND]", bin)),
                        ))
                    }
                }
                ci += 1;
            }
            i += 1;
            continue;
        }
        positional.push(a.clone());
        i += 1;
    }

    if positional.is_empty() {
        return Ok(cli);
    }
    let sub = positional[0].clone();
    let rest: Vec<String> = positional[1..].to_vec();
    let raw_rest: Vec<String> = collect_sub_args(args, &sub);

    match sub.as_str() {
        "print-config" | "pc" => {
            if let Some(extra) = raw_rest.first() {
                if extra == "-h" || extra == "--help" {
                    return Err(out(simple_help(bin, PRINT_CONFIG_ABOUT, "print-config")));
                }
                return Err(err(
                    bin,
                    format!("unexpected argument '{}' found", extra),
                    Some(format!("{} print-config", bin)),
                ));
            }
            cli.command = Some(Command::PrintConfig);
        }
        "import-journals" | "imj" => {
            let mut path: Option<String> = None;
            let mut k = 0;
            while k < raw_rest.len() {
                let a = &raw_rest[k];
                match a.as_str() {
                    "-h" | "--help" => return Err(out(import_help(bin))),
                    "-p" | "--path" => {
                        k += 1;
                        let v = match raw_rest.get(k) {
                            Some(v) => v.clone(),
                            None => {
                                return Err(err(
                                    bin,
                                    "a value is required for '--path <FILE PATH>' but none was supplied".into(),
                                    None,
                                ))
                            }
                        };
                        if path.is_some() {
                            return Err(err(
                                bin,
                                "the argument '--path <FILE PATH>' cannot be used multiple times"
                                    .into(),
                                Some(format!("{} import-journals --path <FILE PATH>", bin)),
                            ));
                        }
                        path = Some(v);
                    }
                    other => {
                        return Err(err(
                            bin,
                            format!("unexpected argument '{}' found", other),
                            Some(format!("{} import-journals --path <FILE PATH>", bin)),
                        ))
                    }
                }
                k += 1;
            }
            match path {
                Some(p) => {
                    cli.command = Some(Command::ImportJournals {
                        path: PathBuf::from(p),
                    })
                }
                None => {
                    return Err(err(
                        bin,
                        "the following required arguments were not provided:\n  --path <FILE PATH>"
                            .into(),
                        Some(format!("{} import-journals --path <FILE PATH>", bin)),
                    ))
                }
            }
        }
        "assign-priority" | "ap" => {
            let mut value: Option<String> = None;
            for a in &raw_rest {
                if a == "-h" || a == "--help" {
                    return Err(out(assign_help(bin)));
                }
                if a.starts_with('-') && a.len() > 1 {
                    let mut msg = format!("unexpected argument '{}' found", a);
                    msg.push_str(&format!(
                        "\n\n  tip: to pass '{}' as a value, use '-- {}'",
                        a, a
                    ));
                    return Err(err(
                        bin,
                        msg,
                        Some(format!("{} assign-priority <PRIORITY>", bin)),
                    ));
                }
                if value.is_some() {
                    return Err(err(
                        bin,
                        format!("unexpected argument '{}' found", a),
                        Some(format!("{} assign-priority <PRIORITY>", bin)),
                    ));
                }
                value = Some(a.clone());
            }
            match value {
                None => {
                    return Err(err(
                        bin,
                        "the following required arguments were not provided:\n  <PRIORITY>".into(),
                        Some(format!("{} assign-priority <PRIORITY>", bin)),
                    ))
                }
                Some(v) => match v.parse::<u32>() {
                    Ok(p) => cli.command = Some(Command::AssignPriority { priority: p }),
                    Err(e) => {
                        return Err(err(
                            bin,
                            format!("invalid value '{}' for '<PRIORITY>': {}", v, parse_int_msg(&e)),
                            None,
                        ))
                    }
                },
            }
        }
        "theme" | "style" => {
            let mut k = 0;
            while k < raw_rest.len() {
                match raw_rest[k].as_str() {
                    "-h" | "--help" => return Err(out(theme_help(bin))),
                    _ => break,
                }
            }
            let subsub = raw_rest.first().cloned();
            let sub_args: Vec<String> = raw_rest.iter().skip(1).cloned().collect();
            let mut resolve = |name: &str, args: &[String]| -> Result<ThemeCommand, Exit> {
                let (about, usage, cmd) = match name {
                    "print-path" | "path" => {
                        (THEME_PATH_ABOUT, "theme print-path", ThemeCommand::PrintPath)
                    }
                    "print-default" | "default" => (
                        THEME_DEFAULT_ABOUT,
                        "theme print-default",
                        ThemeCommand::PrintDefault,
                    ),
                    "write-defaults" | "write" => (
                        THEME_WRITE_ABOUT,
                        "theme write-defaults",
                        ThemeCommand::WriteDefaults,
                    ),
                    other => {
                        return Err(err(
                            bin,
                            format!("unrecognized subcommand '{}'", other),
                            Some(format!("{} theme <COMMAND>", bin)),
                        ))
                    }
                };
                if let Some(a) = args.first() {
                    if a == "-h" || a == "--help" {
                        return Err(out(simple_help(bin, about, usage)));
                    }
                    return Err(err(
                        bin,
                        format!("unexpected argument '{}' found", a),
                        Some(format!("{} {}", bin, usage)),
                    ));
                }
                Ok(cmd)
            };
            match subsub.as_deref() {
                None => {
                    return Err(Exit {
                        code: 2,
                        stdout: String::new(),
                        stderr: theme_help(bin),
                    })
                }
                Some("help") => {
                    return match sub_args.first().map(|s| s.as_str()) {
                        None => Err(out(theme_help(bin))),
                        Some("print-path") | Some("path") => {
                            Err(out(simple_help(bin, THEME_PATH_ABOUT, "theme print-path")))
                        }
                        Some("print-default") | Some("default") => Err(out(simple_help(
                            bin,
                            THEME_DEFAULT_ABOUT,
                            "theme print-default",
                        ))),
                        Some("write-defaults") | Some("write") => Err(out(simple_help(
                            bin,
                            THEME_WRITE_ABOUT,
                            "theme write-defaults",
                        ))),
                        Some(other) => Err(err(
                            bin,
                            format!("unrecognized subcommand '{}'", other),
                            Some(format!("{} theme <COMMAND>", bin)),
                        )),
                    }
                }
                Some(name) => cli.command = Some(Command::Theme(resolve(name, &sub_args)?)),
            }
        }
        "help" => {
            return match rest.first().map(|s| s.as_str()) {
                None => Err(out(root_help(bin, env.config_default, env.log_default))),
                Some("print-config") | Some("pc") => {
                    Err(out(simple_help(bin, PRINT_CONFIG_ABOUT, "print-config")))
                }
                Some("import-journals") | Some("imj") => Err(out(import_help(bin))),
                Some("assign-priority") | Some("ap") => Err(out(assign_help(bin))),
                Some("theme") | Some("style") => Err(out(theme_help(bin))),
                Some("help") => Err(out(root_help(bin, env.config_default, env.log_default))),
                Some(other) => Err(err(
                    bin,
                    format!("unrecognized subcommand '{}'", other),
                    Some(format!("{} [OPTIONS] [COMMAND]", bin)),
                )),
            }
        }
        other => {
            return Err(err(
                bin,
                format!("unrecognized subcommand '{}'", other),
                Some(format!("{} [OPTIONS] [COMMAND]", bin)),
            ))
        }
    }
    Ok(cli)
}

/// Everything after the subcommand token, preserving flags.
fn collect_sub_args(args: &[String], sub: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut found = false;
    let mut skip_next = false;
    for a in args {
        if skip_next {
            skip_next = false;
            continue;
        }
        if !found {
            if a == sub {
                found = true;
            } else if matches!(
                a.as_str(),
                "-j" | "-s" | "-b" | "-c" | "-l"
                    | "--json-file-path"
                    | "--sqlite-file-path"
                    | "--backend-type"
                    | "--config"
                    | "--log"
            ) {
                skip_next = true;
            }
            continue;
        }
        out.push(a.clone());
    }
    out
}

fn parse_int_msg(e: &std::num::ParseIntError) -> String {
    let s = e.to_string();
    if s.contains("empty") {
        "cannot parse integer from empty string".to_string()
    } else if s.contains("too large") {
        "number too large to fit in target type".to_string()
    } else {
        "invalid digit found in string".to_string()
    }
}

fn assign_option(cli: &mut Cli, long: &str, v: &str, bin: &str) -> Result<(), Exit> {
    match long {
        "--json-file-path" => cli.json_file_path = Some(PathBuf::from(v)),
        "--sqlite-file-path" => cli.sqlite_file_path = Some(PathBuf::from(v)),
        "--config" => cli.config = Some(PathBuf::from(v)),
        "--log" => cli.log = Some(PathBuf::from(v)),
        "--backend-type" => {
            cli.backend_type = Some(match v {
                "json" => crate::config::BackendType::Json,
                "sqlite" => crate::config::BackendType::Sqlite,
                other => {
                    return Err(err(
                        bin,
                        format!(
                            "invalid value '{}' for '--backend-type <BACKEND_TYPE>'\n  [possible values: json, sqlite]",
                            other
                        ),
                        None,
                    ))
                }
            })
        }
        _ => {}
    }
    Ok(())
}

fn suggest_long(name: &str) -> Option<(&'static str, &'static str)> {
    let candidates = [
        ("--json-file-path", "FILE PATH"),
        ("--sqlite-file-path", "FILE PATH"),
        ("--backend-type", "BACKEND_TYPE"),
        ("--config", "DIR PATH"),
        ("--verbose", ""),
        ("--log", "FILE PATH"),
        ("--help", ""),
        ("--version", ""),
    ];
    let mut best: Option<(usize, (&'static str, &'static str))> = None;
    for c in candidates {
        if c.1.is_empty() {
            continue;
        }
        let d = levenshtein(&name[2..], &c.0[2..]);
        let threshold = (c.0.len() - 2) / 3 + 1;
        if d <= threshold.max(3) && best.map(|(bd, _)| d < bd).unwrap_or(true) {
            best = Some((d, c));
        }
    }
    best.map(|(_, c)| c)
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

