//! Theme definitions, defaults, TOML (de)serialisation.

use crate::toml::{self, Spanned, TomlError, Value, Writer};
use crate::tui::{modifier, Color, Style};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ThemeStyle {
    pub fg: Color,
    pub bg: Option<Color>,
    pub modifiers: u16,
    pub underline_color: Option<Color>,
}

impl ThemeStyle {
    const fn fg(fg: Color) -> Self {
        ThemeStyle {
            fg,
            bg: None,
            modifiers: 0,
            underline_color: None,
        }
    }
    const fn fg_mod(fg: Color, m: u16) -> Self {
        ThemeStyle {
            fg,
            bg: None,
            modifiers: m,
            underline_color: None,
        }
    }
    const fn fg_bg(fg: Color, bg: Color) -> Self {
        ThemeStyle {
            fg,
            bg: Some(bg),
            modifiers: 0,
            underline_color: None,
        }
    }
    const fn fg_bg_mod(fg: Color, bg: Color, m: u16) -> Self {
        ThemeStyle {
            fg,
            bg: Some(bg),
            modifiers: m,
            underline_color: None,
        }
    }

    pub fn to_style(self) -> Style {
        let mut s = Style::new().fg(self.fg).add(self.modifiers);
        if let Some(bg) = self.bg {
            s = s.bg(bg);
        }
        if let Some(uc) = self.underline_color {
            s.underline_color = Some(uc);
        }
        s
    }

    fn write(&self, w: &mut Writer) {
        w.str_field("fg", &self.fg.name());
        if let Some(bg) = self.bg {
            w.str_field("bg", &bg.name());
        }
        w.str_field("modifiers", &modifier::to_string(self.modifiers));
        if let Some(uc) = self.underline_color {
            w.str_field("underline_color", &uc.name());
        }
    }
}

macro_rules! theme_group {
    ($name:ident, $($field:ident => $default:expr),+ $(,)?) => {
        #[derive(Clone, Debug)]
        pub struct $name {
            $(pub $field: ThemeStyle,)+
        }
        impl Default for $name {
            fn default() -> Self {
                $name { $($field: $default,)+ }
            }
        }
        impl $name {
            fn write(&self, w: &mut Writer) {
                $( self.$field.write(w.table(stringify!($field))); )+
            }
            fn merge(&mut self, table: &[(String, Spanned)]) -> Result<(), TomlError> {
                for (k, v) in table {
                    match k.as_str() {
                        $( stringify!($field) => patch_style(&mut self.$field, v)?, )+
                        _ => {}
                    }
                }
                Ok(())
            }
        }
    };
}

const GREY: Color = Color::Rgb(0xAA, 0xAA, 0xC8);

theme_group!(
    GeneralStyles,
    input_block_active => ThemeStyle::fg(Color::LightYellow),
    input_block_invalid => ThemeStyle::fg(Color::LightRed),
    input_corsur_active => ThemeStyle::fg_bg(Color::Black, Color::LightYellow),
    input_corsur_invalid => ThemeStyle::fg_bg(Color::Black, Color::LightRed),
    list_item_selected => ThemeStyle::fg_mod(Color::LightYellow, modifier::BOLD),
    list_highlight_active => ThemeStyle::fg_bg(Color::Black, Color::LightGreen),
    list_highlight_inactive => ThemeStyle::fg_bg(Color::Black, Color::LightBlue),
);

theme_group!(
    JournalsListStyles,
    block_active => ThemeStyle::fg_mod(Color::Reset, modifier::BOLD),
    block_inactive => ThemeStyle::fg(GREY),
    block_multi_select => ThemeStyle::fg_mod(Color::Yellow, modifier::BOLD | modifier::ITALIC),
    highlight_active => ThemeStyle::fg_bg_mod(Color::Black, Color::LightGreen, modifier::BOLD),
    highlight_inactive => ThemeStyle::fg_bg_mod(Color::Black, Color::LightBlue, modifier::BOLD),
    title_active => ThemeStyle::fg_mod(Color::Reset, modifier::BOLD),
    title_inactive => ThemeStyle::fg_mod(GREY, modifier::BOLD),
    title_selected => ThemeStyle::fg_mod(Color::Yellow, modifier::BOLD),
    date_priority => ThemeStyle::fg(Color::LightBlue),
    tags_default => ThemeStyle::fg_mod(Color::LightCyan, modifier::DIM),
);

theme_group!(
    EditorStyles,
    block_insert => ThemeStyle::fg_mod(Color::LightGreen, modifier::BOLD),
    block_visual => ThemeStyle::fg_mod(Color::Blue, modifier::BOLD),
    block_normal_active => ThemeStyle::fg_mod(Color::Reset, modifier::BOLD),
    block_normal_inactive => ThemeStyle::fg(GREY),
    cursor_normal => ThemeStyle::fg_bg(Color::Black, Color::White),
    cursor_insert => ThemeStyle::fg_bg(Color::Black, Color::LightGreen),
    cursor_visual => ThemeStyle::fg_bg(Color::Black, Color::Blue),
    selection_style => ThemeStyle::fg_bg(Color::Black, Color::White),
);

#[derive(Clone, Debug)]
pub struct MsgBoxColors {
    pub error: Color,
    pub warning: Color,
    pub info: Color,
    pub question: Color,
}

impl Default for MsgBoxColors {
    fn default() -> Self {
        MsgBoxColors {
            error: Color::LightRed,
            warning: Color::Yellow,
            info: Color::LightGreen,
            question: Color::LightBlue,
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Styles {
    pub general: GeneralStyles,
    pub journals_list: JournalsListStyles,
    pub editor: EditorStyles,
    pub msgbox: MsgBoxColors,
}

impl Styles {
    pub fn render(&self) -> String {
        let mut w = Writer::new();
        self.general.write(w.table("general"));
        self.journals_list.write(w.table("journals_list"));
        self.editor.write(w.table("editor"));
        {
            let m = w.table("msgbox");
            m.str_field("error", &self.msgbox.error.name());
            m.str_field("warning", &self.msgbox.warning.name());
            m.str_field("info", &self.msgbox.info.name());
            m.str_field("question", &self.msgbox.question.name());
        }
        w.render()
    }

    pub fn load(source: &str) -> Result<Styles, TomlError> {
        let mut styles = Styles::default();
        let doc = toml::parse(source)?;
        for (key, v) in doc.as_table().unwrap() {
            let table = match &v.value {
                Value::Table(t) => t,
                _ => continue,
            };
            match key.as_str() {
                "general" => styles.general.merge(table)?,
                "journals_list" => styles.journals_list.merge(table)?,
                "editor" => styles.editor.merge(table)?,
                "msgbox" => {
                    for (k, v) in table {
                        let c = parse_color(v)?;
                        match k.as_str() {
                            "error" => styles.msgbox.error = c,
                            "warning" => styles.msgbox.warning = c,
                            "info" => styles.msgbox.info = c,
                            "question" => styles.msgbox.question = c,
                            _ => {}
                        }
                    }
                }
                _ => {}
            }
        }
        Ok(styles)
    }
}

fn parse_color(v: &Spanned) -> Result<Color, TomlError> {
    match &v.value {
        Value::Str(s) => Color::parse(s).ok_or(TomlError {
            message: "Failed to parse Colors".into(),
            line: v.line,
            col: v.col,
            len: v.len,
        }),
        _ => Err(TomlError {
            message:
                "Failed to parse Colors: data did not match any variant of untagged enum ColorFormat"
                    .into(),
            line: v.line,
            col: v.col,
            len: v.len,
        }),
    }
}

fn parse_modifiers(v: &Spanned) -> Result<u16, TomlError> {
    let s = match &v.value {
        Value::Str(s) => s,
        _ => {
            return Err(TomlError {
                message: format!(
                    "invalid type: {} {}, expected a string",
                    v.type_name(),
                    v.debug_value()
                ),
                line: v.line,
                col: v.col,
                len: v.len,
            })
        }
    };
    let mut bits = 0u16;
    for part in s.split('|') {
        let p = part.trim();
        if p.is_empty() {
            continue;
        }
        match modifier::ALL.iter().find(|(n, _)| *n == p) {
            Some((_, b)) => bits |= b,
            None => {
                return Err(TomlError {
                    message: format!("unrecognized named flag `{}`", p),
                    line: v.line,
                    col: v.col,
                    len: v.len,
                })
            }
        }
    }
    Ok(bits)
}

fn patch_style(style: &mut ThemeStyle, v: &Spanned) -> Result<(), TomlError> {
    let table = match &v.value {
        Value::Table(t) => t,
        _ => {
            return Err(TomlError {
                message: format!(
                    "invalid type: {} {}, expected struct Style",
                    v.type_name(),
                    v.debug_value()
                ),
                line: v.line,
                col: v.col,
                len: v.len,
            })
        }
    };
    for (k, v) in table {
        match k.as_str() {
            "fg" => style.fg = parse_color(v)?,
            "bg" => style.bg = Some(parse_color(v)?),
            "underline_color" => style.underline_color = Some(parse_color(v)?),
            "modifiers" => style.modifiers = parse_modifiers(v)?,
            _ => {}
        }
    }
    Ok(())
}

