use config::{BackendType, Settings};
use std::io::Write;
use std::path::{Path, PathBuf};

pub const VERSION: &str = "tui-journal 0.16.1";

fn main() {
    let code = real_main();
    std::process::exit(code);
}

/// Where configuration and themes live for this run.
pub struct ConfigLocation {
    pub config_file: PathBuf,
    pub themes_file: PathBuf,
    /// Set when `--config` pointed at a file rather than a directory.
    pub themes_fallback_notice: bool,
}

fn real_main() -> i32 {
    let argv: Vec<String> = std::env::args().collect();
    let bin = argv
        .first()
        .map(|s| {
            Path::new(s)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "tui-journal".to_string());
    let dirs = paths::Dirs::resolve();
    let env = cli::Env {
        bin: &bin,
        config_default: &dirs.config_dir.to_string_lossy(),
        log_default: &dirs.default_log_file().to_string_lossy(),
        version: VERSION,
    };
    let args: Vec<String> = argv.iter().skip(1).cloned().collect();
    let parsed = match cli::parse(&args, &env) {
        Ok(c) => c,
        Err(e) => {
            print!("{}", e.stdout);
            let _ = std::io::stdout().flush();
            eprint!("{}", e.stderr);
            return e.code;
        }
    };

    let location = match resolve_config_location(&dirs, parsed.config.as_deref()) {
        Ok(l) => l,
        Err(msg) => {
            eprintln!("Error: {}", msg);
            return 1;
        }
    };
    if location.themes_fallback_notice {
        eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
    }

    // `theme` never touches the settings file.
    if let Some(cli::Command::Theme(t)) = &parsed.command {
        return run_theme(t, &location);
    }

    let mut settings = match load_settings(&dirs, &location.config_file) {
        Ok(s) => s,
        Err(msg) => {
            eprintln!("Error: {}", msg);
            return 1;
        }
    };
    apply_cli_overrides(&mut settings, &parsed);

    match &parsed.command {
        Some(cli::Command::PrintConfig) => {
            println!("{}", settings.render());
            0
        }
        Some(cli::Command::Theme(_)) => unreachable!(),
        other => {
            let styles = match load_styles(&location.themes_file) {
                Ok(s) => s,
                Err(msg) => {
                    eprintln!("Error: Error while retrieving app styles\n\nCaused by:\n{}", msg);
                    return 1;
                }
            };
            let startup = match other {
                Some(cli::Command::ImportJournals { path }) => {
                    app::Startup::Import(path.clone())
                }
                Some(cli::Command::AssignPriority { priority }) => {
                    app::Startup::AssignPriority(*priority)
                }
                _ => app::Startup::None,
            };
            match app::run(settings, styles, startup) {
                Ok(()) => 0,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    1
                }
            }
        }
    }
}

fn resolve_config_location(
    dirs: &paths::Dirs,
    custom: Option<&Path>,
) -> Result<ConfigLocation, String> {
    match custom {
        None => Ok(ConfigLocation {
            config_file: dirs.config_dir.join("config.toml"),
            themes_file: dirs.config_dir.join("themes.toml"),
            themes_fallback_notice: false,
        }),
        Some(p) => {
            if p.is_dir() {
                Ok(ConfigLocation {
                    config_file: p.join("config.toml"),
                    themes_file: p.join("themes.toml"),
                    themes_fallback_notice: false,
                })
            } else if p.is_file() {
                Ok(ConfigLocation {
                    config_file: p.to_path_buf(),
                    themes_file: dirs.config_dir.join("themes.toml"),
                    themes_fallback_notice: true,
                })
            } else {
                Err(format!(
                    "Provided custom directory doesn't exit. Path: {}",
                    p.display()
                ))
            }
        }
    }
}

fn load_settings(dirs: &paths::Dirs, file: &Path) -> Result<Settings, String> {
    let source = match std::fs::read_to_string(file) {
        Ok(s) => s,
        Err(_) => return Ok(Settings::defaults(dirs)),
    };
    Settings::load(dirs, &source).map_err(|e| {
        format!(
            "Failed to read configuration file. Error infos: {}",
            e.render(&source)
        )
    })
}

fn load_styles(file: &Path) -> Result<theme::Styles, String> {
    let source = match std::fs::read_to_string(file) {
        Ok(s) => s,
        Err(_) => return Ok(theme::Styles::default()),
    };
    theme::Styles::load(&source).map_err(|e| {
        let rendered = e.render(&source);
        let mut lines = rendered.lines();
        let first = lines.next().unwrap_or("").to_string();
        let mut out = format!(
            "    0: Error while desrializing toml text to styles. File path: {}\n    1: {}",
            file.display(),
            first
        );
        for l in lines {
            out.push_str("\n       ");
            out.push_str(l);
        }
        out.push('\n');
        out
    })
}

fn apply_cli_overrides(settings: &mut Settings, parsed: &cli::Cli) {
    if let Some(p) = &parsed.json_file_path {
        settings.json_backend.file_path = p.clone();
        settings.backend_type = BackendType::Json;
    }
    if let Some(p) = &parsed.sqlite_file_path {
        settings.sqlite_backend.file_path = p.clone();
        settings.backend_type = BackendType::Sqlite;
    }
    if let Some(b) = parsed.backend_type {
        settings.backend_type = b;
    }
}

fn run_theme(cmd: &cli::ThemeCommand, loc: &ConfigLocation) -> i32 {
    match cmd {
        cli::ThemeCommand::PrintPath => {
            println!("{}", loc.themes_file.display());
            0
        }
        cli::ThemeCommand::PrintDefault => {
            println!("{}", theme::Styles::default().render());
            0
        }
        cli::ThemeCommand::WriteDefaults => {
            if loc.themes_file.exists() {
                eprintln!(
                    "Error: Themes file already exists. Path: {}",
                    loc.themes_file.display()
                );
                return 1;
            }
            match std::fs::write(&loc.themes_file, theme::Styles::default().render()) {
                Ok(()) => {
                    println!(
                        "Default themes have been written to {}",
                        loc.themes_file.display()
                    );
                    0
                }
                Err(e) => {
                    eprintln!(
                        "Error: Error while writing default themes to file\n\nCaused by:\n    {}",
                        e
                    );
                    1
                }
            }
        }
    }
}

